// ============================================
// COMPOSANT CALENDRIER DE DISPONIBILITÉ
// ============================================
interface AvailabilityCalendarProps {
  propertyId: number;
  checkIn?: string;
  checkOut?: string;
  onDateSelect?: (checkIn: string, checkOut: string) => void;
}

// ============================================
// COMPOSANT CALENDRIER DE DISPONIBILITÉ
// ============================================
const AvailabilityCalendar = ({ 
  checkIn, 
  checkOut, 
  propertyId,
  onDateSelect 
}: { 
  checkIn: string; 
  checkOut: string; 
  propertyId: number;
  onDateSelect: (start: string, end: string) => void;
}) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [availabilityData, setAvailabilityData] = useState<Record<string, string>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [selectedStart, setSelectedStart] = useState<string | null>(checkIn || null);
  const [selectedEnd, setSelectedEnd] = useState<string | null>(checkOut || null);
  
  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth() + 1;

  useEffect(() => {
    const fetchAvailability = async () => {
      if (!propertyId) return;
      setIsLoading(true);
      try {
        const response = await propertyService.getAvailability(propertyId, year, month);
        if (response?.data) {
          const availability: Record<string, string> = {};
          response.data.forEach((day: any) => {
            availability[day.date] = day.status;
          });
          setAvailabilityData(availability);
        }
      } catch (error) {
        console.error('Erreur récupération disponibilités:', error);
        setAvailabilityData({});
      } finally {
        setIsLoading(false);
      }
    };
    fetchAvailability();
  }, [propertyId, year, month]);

  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear();
    const month = date.getMonth();
    const days = new Date(year, month + 1, 0).getDate();
    const firstDay = new Date(year, month, 1).getDay();
    return { days, firstDay };
  };

  const { days, firstDay } = getDaysInMonth(currentMonth);
  const monthNames = ['Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin', 'Juillet', 'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre'];
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const formatDateKey = (date: Date) => {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  };

  const isDateInPast = (date: Date) => {
    const d = new Date(date);
    d.setHours(0, 0, 0, 0);
    return d < today;
  };

  const isDateBooked = (date: Date) => {
    const key = formatDateKey(date);
    return availabilityData[key] === 'booked' || availabilityData[key] === 'blocked';
  };

  const isDateAvailable = (date: Date) => {
    const key = formatDateKey(date);
    return !isDateInPast(date) && availabilityData[key] === 'available';
  };

  const isDateSelected = (date: Date) => {
    const key = formatDateKey(date);
    return key === selectedStart || key === selectedEnd;
  };

  const isDateInRange = (date: Date) => {
    if (!selectedStart || !selectedEnd) return false;
    const key = formatDateKey(date);
    return key > selectedStart && key < selectedEnd;
  };

  const handleDateClick = (date: Date) => {
    if (isDateInPast(date) || isDateBooked(date)) return;
    
    const key = formatDateKey(date);
    
    if (!selectedStart) {
      setSelectedStart(key);
      return;
    }
    
    if (!selectedEnd && key !== selectedStart) {
      if (key < selectedStart) {
        setSelectedStart(key);
        return;
      }
      setSelectedEnd(key);
      if (onDateSelect) {
        onDateSelect(selectedStart, key);
      }
      return;
    }
    
    setSelectedStart(key);
    setSelectedEnd(null);
  };

  const isCurrentMonth = (date: Date) => {
    return date.getMonth() === month - 1;
  };

  const handlePrevMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1));
  };

  const handleNextMonth = () => {
    setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1));
  };

  const totalNights = selectedStart && selectedEnd ? 
    Math.ceil((new Date(selectedEnd).getTime() - new Date(selectedStart).getTime()) / (1000 * 60 * 60 * 24)) : 0;

  return (
    <div className="text-center">
      <div className="flex items-center justify-between mb-3">
        <button onClick={handlePrevMonth} className="p-1 hover:bg-gray-100 rounded-full transition">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <span className="font-medium text-sm">
          {monthNames[currentMonth.getMonth()]} {currentMonth.getFullYear()}
        </span>
        <button onClick={handleNextMonth} className="p-1 hover:bg-gray-100 rounded-full transition">
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>
      
      <div className="grid grid-cols-7 gap-1 text-xs">
        {['L', 'M', 'M', 'J', 'V', 'S', 'D'].map((day, i) => (
          <div key={i} className="font-medium text-gray-500 py-1">{day}</div>
        ))}
        {Array.from({ length: firstDay === 0 ? 6 : firstDay - 1 }).map((_, i) => (
          <div key={`empty-${i}`} className="py-1" />
        ))}
        {Array.from({ length: days }, (_, i) => i + 1).map((day) => {
          const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
          const isPast = isDateInPast(date);
          const isBooked = isDateBooked(date);
          const isAvailable = isDateAvailable(date);
          const isSelected = isDateSelected(date);
          const isInRange = isDateInRange(date);
          const isCurrentMonthDay = isCurrentMonth(date);
          
          let bgColor = '';
          let textColor = '';
          let cursor = '';
          let hoverEffect = '';
          
          if (!isCurrentMonthDay) {
            textColor = 'text-gray-300';
            cursor = 'cursor-default';
          } else if (isPast) {
            textColor = 'text-gray-300';
            cursor = 'cursor-not-allowed';
            bgColor = 'bg-gray-50';
          } else if (isBooked) {
            bgColor = 'bg-red-50';
            textColor = 'text-red-500';
            cursor = 'cursor-not-allowed';
          } else if (isSelected) {
            bgColor = 'bg-[#00c9a7] text-white';
            textColor = 'text-white';
            cursor = 'cursor-pointer';
            hoverEffect = 'hover:scale-105';
          } else if (isInRange) {
            bgColor = 'bg-[#00c9a7]/20';
          } else if (isAvailable) {
            bgColor = 'hover:bg-green-50';
            textColor = 'text-green-600';
          } else {
            textColor = 'text-gray-800';
            cursor = 'cursor-pointer';
            hoverEffect = 'hover:bg-[#00c9a7]/20';
          }
          
          return (
            <div
              key={day}
              onClick={() => isCurrentMonthDay && !isBooked && !isPast && handleDateClick(date)}
              className={`
                py-1.5 rounded-full text-sm transition-all duration-200
                ${bgColor} ${textColor} ${cursor} ${hoverEffect}
                ${isSelected ? 'shadow-lg shadow-[#00c9a7]/30 scale-105' : ''}
              `}
            >
              {day}
            </div>
          );
        })}
      </div>
      
     
      
      <div className="mt-2 text-xs text-gray-400">
        {!selectedStart && 'Cliquez sur une date pour commencer'}
        {selectedStart && !selectedEnd && 'Sélectionnez la date de fin'}
        {selectedStart && selectedEnd && (
          <span>
            {totalNights} nuit{totalNights > 1 ? 's' : ''}
          </span>
        )}
      </div>
    </div>
  );
};

