      // Divertissement
      has_smart_tv: 'Smart TV',
      has_streaming: 'Netflix / Streaming',
      has_bluetooth_speaker: 'Enceinte Bluetooth',
      has_books: 'Livres',
      
      // Chauffage et climatisation
      has_portable_fan: 'Ventilateur portable',
