      // Caractéristiques de l'emplacement
      has_laundry_nearby: 'Laverie automatique à proximité',
      
      // Sécurité
      has_smoke_detector: 'Détecteur de fumée',
      has_first_aid_kit: 'Trousse de premiers secours',
