// ==================== HOST CALENDAR PAGE ====================

export function HostCalendarPage({ onNavigate, id }: { onNavigate?: (route: Route) => void; id?: string }) {
  const propertyId = id ? parseInt(id) : null;
  const [currentDate, setCurrentDate] = useState(new Date());
  const [isUpdating, setIsUpdating] = useState(false);
  const year = currentDate.getFullYear();
  const month = currentDate.getMonth() + 1;
  const [selectedRange, setSelectedRange] = useState<{ start: string | null; end: string | null }>({ start: null, end: null });
  const [showBlockModal, setShowBlockModal] = useState(false);
  const [blockRange, setBlockRange] = useState({ start: '', end: '', reason: '' });
  const [toastMessage, setToastMessage] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
  
  const [showUnblockModal, setShowUnblockModal] = useState(false);
  const [unblockDate, setUnblockDate] = useState<string | null>(null);
  const [unblockReason, setUnblockReason] = useState('');

  const showToast = (type: 'success' | 'error' | 'info', message: string) => {
    setToastMessage({ type, message });
    setTimeout(() => setToastMessage(null), 4000);
  };

  // ✅ Récupérer le calendrier avec revalidation automatique
  const queryClient = useQueryClient();
  const { data, isLoading, refetch } = useQuery({
    queryKey: ['host-calendar', propertyId, year, month],
    queryFn: () => hostService.getCalendar(propertyId!, year, month),
    enabled: !!propertyId,
    // ✅ Revalider toutes les 30 secondes pour refléter les changements
    refetchInterval: 30000,
    // ✅ Revalider au focus de la page
    refetchOnWindowFocus: true,
    // ✅ Ne pas utiliser les données en cache trop longtemps
    staleTime: 5000,
  });

  // ✅ Écouter les événements de mise à jour des réservations
  useEffect(() => {
    const handleBookingUpdate = () => {
      console.log('🔄 Mise à jour des réservations détectée, rechargement du calendrier...');
      refetch();
    };

    // Écouter les événements personnalisés
    window.addEventListener('booking-updated', handleBookingUpdate);
    window.addEventListener('booking-cancelled', handleBookingUpdate);
    window.addEventListener('booking-rejected', handleBookingUpdate);

    return () => {
      window.removeEventListener('booking-updated', handleBookingUpdate);
      window.removeEventListener('booking-cancelled', handleBookingUpdate);
      window.removeEventListener('booking-rejected', handleBookingUpdate);
    };
  }, [refetch]);

  // ✅ Mutation pour mettre à jour les disponibilités
  const updateAvailabilityMutation = useMutation({
    mutationFn: ({ start, end, status, price, reason }: any) =>
      hostService.updateAvailability(propertyId!, start, end, status, price, reason),
    onSuccess: (response) => {
      console.log('✅ Mise à jour réussie:', response);
      const statusMessage = status === 'available' ? 'débloquée' : 'bloquée';
      showToast('success', `Date ${statusMessage} avec succès !`);
      
      // ✅ Forcer le rechargement des données
      refetch();
      queryClient.invalidateQueries({ queryKey: ['host-calendar', propertyId, year, month] });
      
      // ✅ Déclencher un événement pour informer les autres composants
      window.dispatchEvent(new Event('booking-updated'));
      
      setShowBlockModal(false);
      setShowUnblockModal(false);
      setUnblockDate(null);
      setUnblockReason('');
      setSelectedRange({ start: null, end: null });
    },
    onError: (error: any) => {
      console.error('❌ Erreur mise à jour:', error);
      const message = error.response?.data?.message || 'Erreur lors de la mise à jour';
      showToast('error', message);
    },
  });

  // ✅ Mutation pour les prix spéciaux
  const specialPriceMutation = useMutation({
    mutationFn: ({ start, end, price }: any) =>
      hostService.updateSpecialPrice(propertyId!, start, end, price),
    onSuccess: () => {
      showToast('success', '✅ Prix spécial défini avec succès');
      refetch();
      queryClient.invalidateQueries({ queryKey: ['host-calendar', propertyId, year, month] });
      window.dispatchEvent(new Event('booking-updated'));
    },
    onError: (error: any) => {
      console.error('❌ Erreur prix spécial:', error);
      showToast('error', error.response?.data?.message || 'Erreur lors de la définition du prix spécial');
    },
  });

  // ✅ Fonction pour ouvrir la modale de déblocage
  const handleUnblockClick = (date: string) => {
    setUnblockDate(date);
    setUnblockReason('');
    setShowUnblockModal(true);
  };

  // ✅ Fonction pour confirmer le déblocage
  const handleConfirmUnblock = async () => {
    if (!unblockDate) return;
    
    await updateAvailabilityMutation.mutateAsync({
      start: unblockDate,
      end: unblockDate,
      status: 'available',
      price: null,
      reason: unblockReason || 'Débloqué par l\'hôte'
    });
  };

  const handleDayClick = async (day: any) => {
    console.log('📅 Jour cliqué:', day);
    
    if (day.status === 'booked') {
      showToast('error', '❌ Cette date est déjà réservée, vous ne pouvez pas la modifier');
      return;
    }
    
    if (day.status === 'blocked') {
      handleUnblockClick(day.date);
      return;
    }
    
    if (selectedRange.start === null) {
      setSelectedRange({ start: day.date, end: null });
      showToast('success', `📌 Date de début sélectionnée: ${day.date}`);
      return;
    } 
    
    if (selectedRange.start && selectedRange.end === null) {
      if (day.date < selectedRange.start) {
        showToast('error', '❌ La date de fin doit être après la date de début');
        setSelectedRange({ start: null, end: null });
        return;
      }
      
      const action = confirm(
        `Voulez-vous bloquer du ${selectedRange.start} au ${day.date} ?\n\n` +
        `Cela bloquera toutes les dates entre ces deux jours.`
      );
      
      if (action) {
        await updateAvailabilityMutation.mutateAsync({
          start: selectedRange.start,
          end: day.date,
          status: 'blocked',
          price: null,
          reason: 'Bloqué par l\'hôte'
        });
      }
      setSelectedRange({ start: null, end: null });
      return;
    }
    
    if (day.status === 'available') {
      const action = confirm(
        `Voulez-vous bloquer le ${day.date} ?\n\n` +
        `Cliquez sur "OK" pour bloquer cette date.`
      );
      
      if (action) {
        await updateAvailabilityMutation.mutateAsync({
          start: day.date,
          end: day.date,
          status: 'blocked',
          price: null,
          reason: 'Bloqué par l\'hôte'
        });
      }
    }
  };

  const handleBlockRangeSubmit = async () => {
    if (!blockRange.start || !blockRange.end) {
      showToast('error', '❌ Veuillez sélectionner une plage de dates');
      return;
    }
    
    await updateAvailabilityMutation.mutateAsync({
      start: blockRange.start,
      end: blockRange.end,
      status: 'blocked',
      price: null,
      reason: blockRange.reason || 'Bloqué par l\'hôte'
    });
  };

  const cancelRangeSelection = () => {
    setSelectedRange({ start: null, end: null });
    showToast('info', 'ℹ️ Sélection de plage annulée');
  };

  // ✅ Fonction pour vérifier si une date est dans le passé
  const isDateInPast = (dateStr: string) => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const date = new Date(dateStr);
    date.setHours(0, 0, 0, 0);
    return date < today;
  };

  if (!propertyId) {
    return (
      <div className="min-h-screen bg-[#f4fffe] py-10 text-center">
        <p className="text-gray-500">Sélectionnez d'abord une propriété.</p>
        <button onClick={() => onNavigate?.({ name: 'host-annonces' })} className="mt-4 bg-[#00c9a7] px-4 py-2 rounded-full">
          Voir mes annonces
        </button>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#f4fffe] py-10 text-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto"></div>
        <p className="mt-4 text-gray-500">Chargement du calendrier...</p>
      </div>
    );
  }

  const calendar = data?.data?.calendar || [];
  const propertyTitle = data?.data?.property?.title || 'Propriété';

  return (
    <div className="min-h-screen bg-[#f4fffe] py-10">
      <div className="max-w-[1200px] mx-auto px-4 sm:px-6 lg:px-8">
        {toastMessage && (
          <div className={`fixed top-20 right-4 z-50 p-4 rounded-xl shadow-lg max-w-md ${
            toastMessage.type === 'success' ? 'bg-green-500 text-white' : 
            toastMessage.type === 'error' ? 'bg-red-500 text-white' : 'bg-blue-500 text-white'
          }`}>
            {toastMessage.message}
          </div>
        )}

        <PageSection title={`Calendrier - ${propertyTitle}`} subtitle="Gérez vos disponibilités et tarifs spéciaux.">
          
          <div className="flex flex-wrap gap-3 mb-6">
            {selectedRange.start !== null && selectedRange.end === null ? (
              <button
                onClick={cancelRangeSelection}
                className="px-4 py-2 bg-red-500 text-white rounded-lg text-sm font-medium hover:bg-red-600 transition"
              >
                ❌ Annuler la sélection
              </button>
            ) : (
              <button
                onClick={() => setShowBlockModal(true)}
                className="px-4 py-2 bg-orange-500 text-white rounded-lg text-sm font-medium hover:bg-orange-600 transition"
              >
                🚫 Bloquer une plage de dates
              </button>
            )}
            <button
              onClick={() => {
                refetch();
                showToast('info', '🔄 Calendrier actualisé');
              }}
              className="px-4 py-2 bg-gray-500 text-white rounded-lg text-sm font-medium hover:bg-gray-600 transition"
            >
              🔄 Rafraîchir
            </button>
          </div>

          {selectedRange.start !== null && selectedRange.end === null && (
            <div className="bg-blue-50 border border-blue-200 rounded-xl p-3 mb-4 text-center">
              <p className="text-sm text-blue-700">
                📌 Date de début sélectionnée: <strong>{selectedRange.start}</strong>
                <br />
                Cliquez sur une date de fin pour bloquer la plage.
              </p>
            </div>
          )}

          <div className="bg-white rounded-2xl border p-6">
            <div className="flex justify-between items-center mb-6">
              <button 
                onClick={() => setCurrentDate(new Date(year, month - 2, 1))} 
                className="p-2 rounded-full hover:bg-gray-100 transition"
                disabled={isUpdating}
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <h2 className="text-xl font-semibold">{currentDate.toLocaleString('fr', { month: 'long', year: 'numeric' })}</h2>
              <button 
                onClick={() => setCurrentDate(new Date(year, month, 1))} 
                className="p-2 rounded-full hover:bg-gray-100 transition"
                disabled={isUpdating}
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </div>

            <div className="grid grid-cols-7 gap-1 text-center font-semibold text-gray-500 mb-2">
              {['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'].map(d => <div key={d} className="py-2">{d}</div>)}
            </div>

            <div className="grid grid-cols-7 gap-1">
              {calendar.map((day: any, idx: number) => {
                const dayStatus = day.status || (day.is_available ? 'available' : 'blocked');
                const isSelectedStart = selectedRange.start === day.date;
                const isInRange = selectedRange.start && selectedRange.end === null && day.date > selectedRange.start;
                const isPast = isDateInPast(day.date);
                
                let bgColor = '';
                let hoverEffect = '';
                let cursor = 'cursor-pointer';
                
                if (dayStatus === 'booked' || isPast) {
                  bgColor = 'bg-red-100 text-red-700';
                  cursor = 'cursor-not-allowed';
                  hoverEffect = '';
                } else if (dayStatus === 'blocked') {
                  bgColor = 'bg-orange-100 text-orange-700';
                  hoverEffect = 'hover:bg-orange-200 hover:scale-105';
                } else {
                  bgColor = 'bg-green-50 text-green-700';
                  hoverEffect = 'hover:bg-green-100 hover:scale-105';
                }
                
                if (isSelectedStart) {
                  bgColor = 'ring-2 ring-[#00c9a7] shadow-lg bg-[#00c9a7]/10';
                }
                if (isInRange) {
                  bgColor = 'bg-blue-100';
                }
                
                // ✅ Afficher les dates passées comme réservées
                const displayStatus = isPast ? '📅 Passée' : 
                  dayStatus === 'booked' ? '📅 Réservé' :
                  dayStatus === 'blocked' ? '🚫 Bloqué' : '✅ Dispo';
                
                return (
                  <div
                    key={idx}
                    className={`p-2 border rounded-xl text-center transition-all duration-200 ${bgColor} ${hoverEffect} ${cursor}`}
                    onClick={() => !isUpdating && dayStatus !== 'booked' && !isPast && handleDayClick(day)}
                  >
                    <div className="text-sm font-medium">{day.day}</div>
                    {day.special_price && (
                      <div className="text-xs text-green-600 font-semibold mt-1">
                        {day.special_price.toLocaleString()} FCFA
                      </div>
                    )}
                    <div className="text-xs mt-1">
                      {displayStatus}
                    </div>
                  </div>
                );
              })}
            </div>



            {(updateAvailabilityMutation.isPending || specialPriceMutation.isPending || isUpdating) && (
              <div className="mt-4 text-center text-sm text-gray-500">
                <div className="inline-flex items-center gap-2">
                  <div className="w-4 h-4 border-2 border-gray-500 border-t-transparent rounded-full animate-spin" />
                  Mise à jour en cours...
                </div>
              </div>
            )}
          </div>
        </PageSection>
      </div>

      {/* Modal pour bloquer une plage de dates */}
      {showBlockModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl">
            <h3 className="text-xl font-semibold text-[#0F2940] mb-4">🚫 Bloquer une plage de dates</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date de début</label>
                <input
                  type="date"
                  value={blockRange.start}
                  onChange={(e) => setBlockRange({ ...blockRange, start: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#00c9a7] focus:border-transparent"
                  min={new Date().toISOString().split('T')[0]}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Date de fin</label>
                <input
                  type="date"
                  value={blockRange.end}
                  onChange={(e) => setBlockRange({ ...blockRange, end: e.target.value })}
                  className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#00c9a7] focus:border-transparent"
                  min={blockRange.start || new Date().toISOString().split('T')[0]}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Raison (optionnel)</label>
                <input
                  type="text"
                  value={blockRange.reason}
                  onChange={(e) => setBlockRange({ ...blockRange, reason: e.target.value })}
                  placeholder="Travaux, indisponibilité, etc."
                  className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#00c9a7] focus:border-transparent"
                />
              </div>
              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => setShowBlockModal(false)}
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-xl text-gray-700 hover:bg-gray-50 transition"
                >
                  Annuler
                </button>
                <button
                  onClick={handleBlockRangeSubmit}
                  disabled={updateAvailabilityMutation.isPending}
                  className="flex-1 px-4 py-2 bg-orange-500 text-white rounded-xl hover:bg-orange-600 transition disabled:opacity-50"
                >
                  {updateAvailabilityMutation.isPending ? 'Blocage...' : 'Bloquer'}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Modal de déblocage */}
      {showUnblockModal && unblockDate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl animate-fadeInUp">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-10 h-10 rounded-full bg-green-100 flex items-center justify-center">
                <CheckCircle className="w-5 h-5 text-green-600" />
              </div>
              <h3 className="text-xl font-semibold text-[#0F2940]">Débloquer la date</h3>
            </div>
            
            <p className="text-gray-600 mb-4">
              Êtes-vous sûr de vouloir débloquer le <strong className="text-[#0F2940]">{unblockDate}</strong> ?
              <br />
              <span className="text-sm text-gray-400">Cette date redeviendra disponible pour les réservations.</span>
            </p>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Raison du déblocage (optionnel)</label>
                <input
                  type="text"
                  value={unblockReason}
                  onChange={(e) => setUnblockReason(e.target.value)}
                  placeholder="Indisponibilité terminée, etc."
                  className="w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#00c9a7] focus:border-transparent"
                />
              </div>
              
              <div className="flex gap-3 pt-4">
                <button
                  onClick={() => {
                    setShowUnblockModal(false);
                    setUnblockDate(null);
                    setUnblockReason('');
                  }}
                  className="flex-1 px-4 py-2 border border-gray-300 rounded-xl text-gray-700 hover:bg-gray-50 transition"
                >
                  Annuler
                </button>
                <button
                  onClick={handleConfirmUnblock}
                  disabled={updateAvailabilityMutation.isPending}
                  className="flex-1 px-4 py-2 bg-green-500 text-white rounded-xl hover:bg-green-600 transition disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {updateAvailabilityMutation.isPending ? (
                    <>
                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                      Déblocage...
                    </>
                  ) : (
                    <>
                      <CheckCircle className="w-4 h-4" />
                      Débloquer
                    </>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
// ==================== HOST RESERVATIONS PAGE ====================


interface Route {
    name: string;
    id?: string;
}

interface HostReservationsPageProps {
    onNavigate?: (route: Route) => void;
}

export function HostReservationsPage({ onNavigate }: HostReservationsPageProps) {
    const queryClient = useQueryClient();
    const { data, isLoading, error } = useQuery({
        queryKey: ['host-reservations'],
        queryFn: () => hostService.getHostBookings(),
    });

    const confirmMutation = useMutation({
        mutationFn: (id: number) => hostService.confirmBooking(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['host-reservations'] });
        },
        onError: (error: any) => {
            console.error('Erreur lors de la confirmation:', error);
            alert('Erreur lors de la confirmation de la réservation');
        },
    });

    const declineMutation = useMutation({
        mutationFn: (id: number) => hostService.declineBooking(id),
        onSuccess: () => {
            queryClient.invalidateQueries({ queryKey: ['host-reservations'] });
        },
        onError: (error: any) => {
            console.error('Erreur lors du refus:', error);
            alert('Erreur lors du refus de la réservation');
        },
    });

    // ✅ Récupérer les données avec la structure correcte
    const bookings = data?.data?.data || data?.data || [];

    // ✅ Fonction pour formater les montants
    const formatAmount = (amount: any): string => {
        if (!amount && amount !== 0) return '0 FCFA';
        if (typeof amount === 'string') {
            // Supprimer les espaces et convertir en nombre
            const cleanAmount = amount.replace(/\s/g, '');
            const num = parseFloat(cleanAmount);
            if (isNaN(num)) return '0 FCFA';
            return `${num.toLocaleString()} FCFA`;
        }
        const num = typeof amount === 'number' ? amount : parseFloat(amount);
        if (isNaN(num)) return '0 FCFA';
        return `${num.toLocaleString()} FCFA`;
    };

    // ✅ Fonction pour obtenir le statut en français
    const getStatusLabel = (status: string): string => {
        const statusMap: Record<string, string> = {
            'pending': 'En attente',
            'confirmed': 'Confirmée',
            'cancelled': 'Annulée',
            'completed': 'Terminée',
        };
        return statusMap[status] || status;
    };

    // ✅ Fonction pour obtenir la couleur du statut
    const getStatusColor = (status: string): string => {
        const colorMap: Record<string, string> = {
            'pending': 'bg-yellow-100 text-yellow-800',
            'confirmed': 'bg-green-100 text-green-800',
            'cancelled': 'bg-red-100 text-red-800',
            'completed': 'bg-blue-100 text-blue-800',
        };
        return colorMap[status] || 'bg-gray-100 text-gray-800';
    };

    if (isLoading) {
        return (
            <div className="bg-white min-h-screen py-10">
                <div className="max-w-[1100px] mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="text-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto"></div>
                        <p className="mt-4 text-gray-500">Chargement des réservations...</p>
                    </div>
                </div>
            </div>
        );
    }

    if (error) {
        return (
            <div className="bg-white min-h-screen py-10">
                <div className="max-w-[1100px] mx-auto px-4 sm:px-6 lg:px-8">
                    <div className="bg-red-50 border border-red-200 rounded-2xl p-8 text-center">
                        <div className="text-4xl mb-4">❌</div>
                        <h3 className="text-lg font-semibold text-red-700 mb-2">Erreur de chargement</h3>
                        <p className="text-red-600">Impossible de charger les réservations. Veuillez réessayer.</p>
                        <button
                            onClick={() => window.location.reload()}
                            className="mt-4 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700"
                        >
                            Réessayer
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white min-h-screen py-10">
            <div className="max-w-[1100px] mx-auto px-4 sm:px-6 lg:px-8">
                <PageSection title="Réservations hôte" subtitle="Suivez les demandes et les séjours en cours.">
                    {bookings.length === 0 ? (
                        <div className="bg-[#f4fffe] rounded-3xl border border-[#e2f5f2] p-12 text-center">
                            <div className="text-6xl mb-4">📅</div>
                            <h3 className="text-xl font-semibold text-[#0f2940] mb-2">
                                Aucune réservation
                            </h3>
                            <p className="text-gray-500">
                                Vous n'avez pas encore reçu de réservation.
                            </p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {bookings.map((booking: any) => (
                                <div 
                                    key={booking.id} 
                                    className="rounded-3xl border border-[#e2f5f2] p-6 bg-[#f4fffe] hover:shadow-lg transition-shadow"
                                >
                                    <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                                        {/* Informations réservation */}
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-2 flex-wrap">
                                                <span className="text-xs font-mono bg-gray-200 px-2 py-1 rounded">
                                                    #{booking.reference || booking.id}
                                                </span>
                                                <span className={`text-xs px-2 py-1 rounded-full font-medium ${getStatusColor(booking.status)}`}>
                                                    {getStatusLabel(booking.status)}
                                                </span>
                                                {booking.payment_status && (
                                                    <span className={`text-xs px-2 py-1 rounded-full font-medium ${
                                                        booking.payment_status === 'paid' 
                                                            ? 'bg-green-100 text-green-800' 
                                                            : 'bg-yellow-100 text-yellow-800'
                                                    }`}>
                                                        {booking.payment_status === 'paid' ? 'Payé' : 'En attente de paiement'}
                                                    </span>
                                                )}
                                            </div>
                                            
                                            <h3 className="text-xl font-semibold text-[#0f2940]">
                                                {booking.property?.title || 'Propriété'}
                                            </h3>
                                            
                                            <p className="text-sm text-[#6b7280] mt-1">
                                                {booking.property?.district}, {booking.property?.city}
                                            </p>
                                            
                                            {/* ✅ Utilisation des nouvelles structures guest et dates */}
                                            <div className="mt-3 space-y-2">
                                                <div className="flex items-center gap-2">
                                                    {booking.guest?.photo && (
                                                        <img 
                                                            src={booking.guest.photo} 
                                                            alt={booking.guest.name}
                                                            className="w-6 h-6 rounded-full"
                                                        />
                                                    )}
                                                    <p className="text-sm">
                                                        <span className="text-gray-500">👤 Voyageur:</span>{' '}
                                                        <span className="font-medium">{booking.guest?.name || 'Non renseigné'}</span>
                                                    </p>
                                                </div>
                                                
                                                {booking.guest?.phone && (
                                                    <p className="text-sm">
                                                        <span className="text-gray-500">📞 Téléphone:</span>{' '}
                                                        <span className="font-medium">{booking.guest.phone}</span>
                                                    </p>
                                                )}
                                                
                                                <p className="text-sm">
                                                    <span className="text-gray-500">👥 Nombre de voyageurs:</span>{' '}
                                                    <span className="font-medium">{booking.guests_count || 1}</span>
                                                </p>
                                                
                                                <p className="text-sm">
                                                    <span className="text-gray-500">🌙 Nuits:</span>{' '}
                                                    <span className="font-medium">{booking.dates?.nights || 0}</span>
                                                </p>
                                                
                                                <p className="text-sm">
                                                    <span className="text-gray-500">📅 Dates:</span>{' '}
                                                    <span className="font-medium">
                                                        {booking.dates?.check_in || '--'} → {booking.dates?.check_out || '--'}
                                                    </span>
                                                </p>
                                            </div>
                                        </div>
                                        
                                        {/* Montant et actions */}
                                        <div className="text-left lg:text-right">
                                            <div className="mb-3">
                                                <div className="text-sm text-gray-500">Sous-total</div>
                                                <div className="font-medium">{formatAmount(booking.amount?.subtotal)}</div>
                                                <div className="text-sm text-gray-500 mt-1">Frais de service</div>
                                                <div className="font-medium">{formatAmount(booking.amount?.service_fee)}</div>
                                                {booking.amount?.cleaning_fee && parseFloat(booking.amount.cleaning_fee.replace(/\s/g, '')) > 0 && (
                                                    <>
                                                        <div className="text-sm text-gray-500 mt-1">Frais de ménage</div>
                                                        <div className="font-medium">{formatAmount(booking.amount?.cleaning_fee)}</div>
                                                    </>
                                                )}
                                                <div className="border-t border-gray-200 mt-2 pt-2">
                                                    <div className="text-lg font-bold text-[#00c9a7]">
                                                        {formatAmount(booking.amount?.total)}
                                                    </div>
                                                </div>
                                            </div>
                                            
                                            <div className="flex flex-wrap gap-3 mt-4 justify-end">
                                                {booking.status === 'pending' ? (
                                                    <>
                                                        <button
                                                            onClick={() => confirmMutation.mutate(booking.id)}
                                                            disabled={confirmMutation.isPending}
                                                            className="rounded-full bg-green-500 text-white px-5 py-2 text-sm hover:bg-green-600 transition-colors disabled:opacity-50 flex items-center gap-1"
                                                        >
                                                            {confirmMutation.isPending && confirmMutation.variables === booking.id ? (
                                                                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                                                            ) : (
                                                                <CheckCircle className="w-4 h-4" />
                                                            )}
                                                            Accepter
                                                        </button>
                                                        <button
                                                            onClick={() => declineMutation.mutate(booking.id)}
                                                            disabled={declineMutation.isPending}
                                                            className="rounded-full border border-red-300 text-red-600 px-5 py-2 text-sm hover:bg-red-50 transition-colors disabled:opacity-50 flex items-center gap-1"
                                                        >
                                                            {declineMutation.isPending && declineMutation.variables === booking.id ? (
                                                                <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-red-600"></div>
                                                            ) : (
                                                                <XCircle className="w-4 h-4" />
                                                            )}
                                                            Refuser
                                                        </button>
                                                    </>
                                                ) : (
                                                    <span className={`px-4 py-2 rounded-full text-sm font-medium ${getStatusColor(booking.status)}`}>
                                                        {getStatusLabel(booking.status)}
                                                    </span>
                                                )}

                                      <button
                                          onClick={() => onNavigate?.({ name: 'host-messages', id: booking.id.toString() })}
                                          className="border border-[#00c9a7] text-[#00c9a7] rounded-full px-5 py-2 text-sm hover:bg-[#00c9a7] hover:text-white transition-colors flex items-center gap-1"
                                      >
                                          <MessageCircle className="w-4 h-4" />
                                          Message
                                      </button>
                                                                                  </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </PageSection>
            </div>
        </div>
    );
}

// ====================Host MESSAGES PAGE ====================

interface Route {
    name: string;
    id?: string;
}

interface HostMessagesPageProps {
    onNavigate?: (route: Route) => void;
    id?: string; // bookingId
}

// ============================================
// COMPOSANT CHAT VIEW POUR HÔTES
// ============================================
const HostChatView = ({ 
  conversation,
  messages, 
  messagesLoading, 
  user, 
  onSendMessage,
  isSending,
  onBack,
  guestName,
  propertyTitle,
  isInquiry,
  bookingDetails
}: { 
  conversation: any;
  messages: any[];
  messagesLoading: boolean;
  user: any;
  onSendMessage: (message: string) => void;
  isSending: boolean;
  onBack?: () => void;
  guestName: string;
  propertyTitle: string;
  isInquiry: boolean;
  bookingDetails?: any;
}) => {
  const [messageInput, setMessageInput] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    setTimeout(() => {
      scrollToEnd(messagesEndRef.current);
    }, 100);
  }, [messages]);

  if (!conversation) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-gray-400 p-4">
        <MessageCircle className="w-16 h-16 mb-4 opacity-50" />
        <p className="text-lg font-medium text-center">Sélectionnez une conversation</p>
        <p className="text-sm text-center">Les messages des voyageurs apparaissent ici</p>
      </div>
    );
  }

  const handleSend = () => {
    if (!messageInput.trim()) return;
    onSendMessage(messageInput.trim());
    setMessageInput('');
    if (textareaRef.current) {
      textareaRef.current.style.height = '44px';
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessageInput(e.target.value);
    const textarea = e.target;
    textarea.style.height = '44px';
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
  };

  const displayName = guestName || 'Voyageur';
  const displayTitle = propertyTitle || 'Conversation';

  // ✅ Extraire les détails de réservation
  const checkIn = bookingDetails?.check_in || conversation?.booking?.check_in;
  const checkOut = bookingDetails?.check_out || conversation?.booking?.check_out;
  const guests = bookingDetails?.guests || conversation?.booking?.guests;
  const totalPrice = bookingDetails?.total_price || conversation?.booking?.total_price;

  return (
    <div className="flex flex-col h-full bg-white">
      {/* En-tête */}
      <div className="p-3 sm:p-4 border-b bg-white flex-shrink-0">
        <div className="flex items-center gap-3">
          {onBack && (
            <button 
              onClick={onBack}
              className="lg:hidden p-2 -ml-2 rounded-full hover:bg-gray-100 transition"
            >
              <ArrowLeft className="w-5 h-5 text-gray-600" />
            </button>
          )}
          <div className="w-10 h-10 rounded-full bg-[#00c9a7] flex items-center justify-center text-white font-bold flex-shrink-0 text-sm">
            {displayName.charAt(0).toUpperCase()}
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-semibold text-gray-900 truncate">{displayName}</p>
            <div className="flex items-center gap-1 text-xs text-gray-500 truncate">
              {isInquiry ? (
                <>
                  <Sparkles className="w-3 h-3 flex-shrink-0 text-[#00c9a7]" />
                  <span className="truncate">{displayTitle}</span>
                  <span className="flex-shrink-0 text-[#00c9a7]">· Demande</span>
                </>
              ) : (
                <span className="truncate">{displayTitle}</span>
              )}
            </div>
          </div>
          {conversation?.guest?.phone && (
            <a href={`tel:${conversation.guest.phone}`} className="p-2 rounded-full hover:bg-gray-100 transition flex-shrink-0">
              <Phone className="w-4 h-4 text-gray-500" />
            </a>
          )}
        </div>
        
        {/* ✅ Détails de la réservation */}
        {(checkIn || checkOut || guests || totalPrice) && (
          <div className="mt-2 p-2 bg-gray-50 rounded-lg border border-gray-100">
            <div className="flex flex-wrap items-center gap-3 text-xs text-gray-600">
              {checkIn && checkOut && (
                <span className="flex items-center gap-1">
                  <Calendar className="w-3 h-3 text-[#00c9a7]" />
                  {checkIn} → {checkOut}
                </span>
              )}
              {guests && (
                <span className="flex items-center gap-1">
                  <Users className="w-3 h-3 text-[#00c9a7]" />
                  {guests} voyageur{guests > 1 ? 's' : ''}
                </span>
              )}
              {totalPrice && (
                <span className="flex items-center gap-1 font-medium text-[#00c9a7]">
                  <DollarSign className="w-3 h-3" />
                  {totalPrice.toLocaleString()} FCFA
                </span>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-3 sm:p-4 space-y-3 bg-gray-50">
        {messagesLoading ? (
          <div className="text-center py-10">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#00c9a7] mx-auto"></div>
            <p className="text-gray-500 mt-2 text-sm">Chargement des messages...</p>
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-10 text-gray-400">
            <MessageCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
            <p className="text-sm">Aucun message</p>
            <p className="text-xs mt-1">Soyez le premier à répondre !</p>
          </div>
        ) : (
          messages.map((msg: any, index: number) => {
            const isFromMe = msg.sender_id === user?.id || msg.is_from_me === true || msg.is_from_me === 1;
            
            // ✅ Déterminer le nom de l'expéditeur
            let senderName = '';
            if (isFromMe) {
              senderName = user?.first_name ? `${user.first_name} ${user.last_name || ''}` : 'Moi';
            } else {
              senderName = conversation?.guest?.name || conversation?.booking?.guest?.name || 'Voyageur';
            }
            
            return (
              <div key={msg.id || index} className={`flex ${isFromMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] sm:max-w-[70%] rounded-2xl p-3 ${
                  isFromMe ? 'bg-[#00c9a7] text-white' : 'bg-white text-gray-800 shadow-sm'
                }`}>
                  {!isFromMe && (
                    <p className="text-xs font-semibold text-[#00c9a7] mb-1">{senderName}</p>
                  )}
                  <p className="text-sm sm:text-base whitespace-pre-wrap break-words">{msg.message}</p>
                  <p className={`text-xs mt-1 ${isFromMe ? 'text-white/70' : 'text-gray-400'}`}>
                    {messageTime(msg.created_at)}
                  </p>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Zone de saisie */}
      <div className="p-2 sm:p-4 border-t bg-white flex-shrink-0">
        <div className="flex gap-2 items-end">
          <textarea
            ref={textareaRef}
            value={messageInput}
            onChange={handleTextareaChange}
            onKeyPress={handleKeyPress}
            placeholder={`Répondre à ${displayName}...`}
            rows={1}
            className="flex-1 border rounded-full px-3 sm:px-4 py-2 sm:py-2.5 focus:outline-none focus:ring-2 focus:ring-[#00c9a7] resize-none text-sm sm:text-base"
            style={{ 
              minHeight: '40px', 
              maxHeight: '100px',
              lineHeight: '1.5'
            }}
            disabled={isSending}
          />
          <button
            onClick={handleSend}
            disabled={!messageInput.trim() || isSending}
            className="bg-[#00c9a7] text-white rounded-full p-2.5 sm:p-3 disabled:opacity-50 hover:bg-[#00b89a] transition flex-shrink-0"
          >
            {isSending ? (
              <div className="animate-spin rounded-full h-4 w-4 sm:h-5 sm:w-5 border-b-2 border-white" />
            ) : (
              <Send className="w-4 h-4 sm:w-5 sm:h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

// ============================================
// COMPOSANT PRINCIPAL HOST MESSAGES
// ============================================
export function HostMessagesPage({ onNavigate, id }: HostMessagesPageProps) {
  const { user } = useAuth();
  const [selectedConversation, setSelectedConversation] = useState<any>(null);
  const [selectedType, setSelectedType] = useState<'booking' | 'inquiry'>('booking');
  const [selectedGuestId, setSelectedGuestId] = useState<number | null>(null);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const queryClient = useQueryClient();

  // Récupérer les conversations
  const { data: conversationsData, isLoading: convLoading, refetch: refetchConversations } = useQuery({
    queryKey: ['host-messages-conversations'],
    queryFn: () => hostService.getHostConversations(),
  });

  // Récupérer les messages d'une conversation
  const { data: messagesData, refetch: refetchMessages, isLoading: messagesLoading } = useQuery({
    queryKey: ['host-messages', selectedType, selectedConversation?.booking?.id, selectedGuestId],
    queryFn: () => {
      if (selectedType === 'booking' && selectedConversation?.booking?.id) {
        return hostService.getHostMessages(selectedConversation.booking.id.toString());
      } else if (selectedType === 'inquiry' && selectedGuestId) {
        return hostService.getInquiryMessages(selectedGuestId);
      }
      return Promise.reject('No selection');
    },
    enabled: !!selectedConversation,
  });

  // Mutation pour envoyer un message
  const sendMutation = useMutation({
    mutationFn: (message: string) => {
      if (selectedType === 'booking' && selectedConversation?.booking?.id) {
        return hostService.sendHostMessage(selectedConversation.booking.id.toString(), { message });
      } else if (selectedType === 'inquiry' && selectedGuestId) {
        return hostService.sendInquiryReply(selectedGuestId, { message });
      }
      throw new Error('Invalid conversation type');
    },
    onSuccess: () => {
      refetchMessages();
      queryClient.invalidateQueries({ queryKey: ['host-messages-conversations'] });
      toast.success('Message envoyé');
    },
    onError: (err: any) => {
      console.error('❌ Erreur envoi:', err);
      toast.error(err?.response?.data?.message || 'Erreur lors de l\'envoi');
    },
  });

  const conversations = conversationsData?.data || [];
  const messages = messagesData?.data?.messages || [];

  // Ouvrir un fil le marque lu côté serveur : on rafraîchit la liste.
  useEffect(() => {
    if (messagesData) queryClient.invalidateQueries({ queryKey: ['host-messages-conversations'] });
  }, [selectedConversation?.booking?.id, selectedGuestId, messages.length]); // eslint-disable-line react-hooks/exhaustive-deps
  const currentBooking = messagesData?.data?.booking;

  // ✅ Sélectionner une conversation
  const handleSelectConversation = (conv: any) => {
    console.log('📌 Sélection conversation:', conv);
    
    setSelectedConversation(conv);
    if (conv.type === 'inquiry') {
      setSelectedType('inquiry');
      setSelectedGuestId(conv.booking.guest?.id);
    } else {
      setSelectedType('booking');
      setSelectedGuestId(null);
    }
    setMobileMenuOpen(false);
  };

  // ✅ Envoyer un message
  const handleSendMessage = (message: string) => {
    if (!message.trim() || !selectedConversation) return;
    sendMutation.mutate(message);
  };

  // ✅ Extraire les données pour le chat
  const getChatData = () => {
    if (!selectedConversation) return null;
    
    const isInquiry = selectedType === 'inquiry';
    const guest = selectedConversation.booking?.guest || selectedConversation.guest || {};
    const property = selectedConversation.booking?.property || {};
    const booking = selectedConversation.booking || {};
    
    return {
      guestName: guest.name || 'Voyageur',
      propertyTitle: property.title || (isInquiry ? 'Demande d\'information' : 'Réservation'),
      isInquiry,
      bookingDetails: {
        check_in: booking.check_in,
        check_out: booking.check_out,
        guests: booking.guests,
        total_price: booking.total_price
      }
    };
  };

  const chatData = getChatData();

  if (convLoading) {
    return (
      <div className="bg-white min-h-screen py-10">
        <div className="max-w-[1200px] mx-auto px-4">
          <div className="text-center py-20">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#f4fffe] min-h-screen py-4 sm:py-10">
      <div className="max-w-[1200px] mx-auto px-3 sm:px-4 lg:px-8">
        <div className="flex justify-between items-center mb-4 sm:mb-6">
          <h1 className="text-xl sm:text-2xl font-bold text-[#0F2940] flex items-center gap-2">
            <MessageCircle className="w-5 h-5 sm:w-6 sm:h-6 text-[#00c9a7]" />
            <span className="hidden sm:inline">Messagerie Hôte</span>
            <span className="sm:hidden">Messages</span>
          </h1>
          <button onClick={() => onNavigate?.({ name: 'host-dashboard' })} className="text-sm text-gray-500 hover:text-[#00c9a7] transition">
            ← Retour
          </button>
        </div>

        <div className="flex flex-col lg:flex-row gap-4 sm:gap-6 bg-white rounded-2xl sm:rounded-3xl shadow-md overflow-hidden border border-[#e2f5f2] min-h-[600px]">
          
          {/* Liste des conversations */}
          {/* Sur mobile : la liste s'affiche d'office tant qu'aucune conversation
              n'est ouverte (elle était cachée derrière un bouton ☰). */}
          <div className={`
            ${mobileMenuOpen || !selectedConversation ? 'block' : 'hidden'} 
            lg:block lg:w-1/3 border-r bg-[#f4fffe]
            ${mobileMenuOpen ? 'fixed inset-0 z-50 bg-white p-4 overflow-y-auto' : ''}
          `}>
            {mobileMenuOpen && (
              <button 
                onClick={() => setMobileMenuOpen(false)}
                className="lg:hidden absolute top-4 right-4 p-2 rounded-full hover:bg-gray-100"
              >
                <X className="w-5 h-5 text-gray-600" />
              </button>
            )}
            
            <div className={`p-3 sm:p-4 border-b font-semibold bg-white flex justify-between items-center ${mobileMenuOpen ? 'mt-12' : ''}`}>
              <span>Conversations ({conversations.length})</span>
              <button 
                onClick={() => refetchConversations()} 
                className="text-xs text-[#00c9a7] hover:underline flex items-center gap-1"
              >
                <RefreshCw className="w-4 h-4" />
                <span className="hidden sm:inline">Rafraîchir</span>
              </button>
            </div>
            
            <div className="divide-y max-h-[calc(100vh-200px)] overflow-y-auto">
              {conversations.length === 0 ? (
                <div className="p-8 text-center text-gray-400">
                  <MessageCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
                  <p>Aucune conversation</p>
                </div>
              ) : (
                conversations.map((conv: any, index: number) => {
                  const isInquiry = conv.type === 'inquiry';
                  const guestName = conv.booking.guest?.name || conv.guest?.name || 'Voyageur';
                  const propertyTitle = conv.booking.property?.title || 
                                        conv.booking.service_name || 
                                        (isInquiry ? 'Demande d\'information' : 'Réservation');
                  
                  const isSelected = selectedConversation === conv ||
                    (selectedType === 'inquiry' && selectedGuestId === conv.booking.guest?.id);
                  
                  return (
                    <button
                      key={conv.id || index}
                      onClick={() => handleSelectConversation(conv)}
                      className={`w-full text-left p-3 sm:p-4 hover:bg-white transition ${
                        isSelected ? 'bg-white shadow-sm' : ''
                      }`}
                    >
                      <div className="flex justify-between items-start">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="font-medium text-gray-900 text-sm sm:text-base truncate">
                              {guestName}
                            </p>
                            {conv.unread_count > 0 && (
                              <span className="bg-red-500 text-white text-xs rounded-full px-2 py-0.5 flex-shrink-0">
                                {conv.unread_count}
                              </span>
                            )}
                          </div>
                          <p className="text-xs sm:text-sm text-gray-500 truncate">{propertyTitle}</p>
                          {isInquiry && (
                            <span className="text-[10px] text-[#00c9a7] mt-0.5 inline-block">✉️ Demande d'information</span>
                          )}
                          {conv.booking.check_in && conv.booking.check_out && (
                            <p className="text-xs text-gray-400 mt-0.5">
                              📅 {conv.booking.check_in} → {conv.booking.check_out}
                            </p>
                          )}
                        </div>
                        {conv.last_message && (
                          <span className="text-[10px] sm:text-xs text-gray-400 flex-shrink-0 ml-2">
                            {conv.last_message.sent_at}
                          </span>
                        )}
                      </div>
                      {conv.last_message && (
                        <p className="text-xs text-gray-400 mt-2 truncate">
                          {conv.last_message.message}
                        </p>
                      )}
                    </button>
                  );
                })
              )}
            </div>
          </div>

          {/* Zone de chat avec HostChatView */}
          <div className={`${selectedConversation ? 'flex' : 'hidden lg:flex'} lg:w-2/3 flex-col h-[calc(100dvh-13rem)] min-h-[420px] lg:h-[600px] relative`}>
            <button 
              onClick={() => setMobileMenuOpen(true)}
              className="lg:hidden absolute top-3 left-3 z-10 p-2 rounded-full bg-white shadow-md hover:bg-gray-50"
            >
              <Menu className="w-5 h-5 text-gray-600" />
            </button>

            {selectedConversation && chatData ? (
              <HostChatView 
                conversation={selectedConversation}
                messages={messages}
                messagesLoading={messagesLoading}
                user={user}
                onSendMessage={handleSendMessage}
                isSending={sendMutation.isPending}
                onBack={() => setMobileMenuOpen(true)}
                guestName={chatData.guestName}
                propertyTitle={chatData.propertyTitle}
                isInquiry={chatData.isInquiry}
                bookingDetails={chatData.bookingDetails}
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-[#f4fffe] rounded-b-2xl">
                <MessageCircle className="w-16 h-16 mb-4 opacity-50" />
                <p className="text-lg font-medium">Sélectionnez une conversation</p>
                <p className="text-sm">Pour commencer à discuter avec un voyageur</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ==================== Host Favorites PAGE ====================


interface Route {
    name: string;
    id?: string;
}

interface HostFavoritesPageProps {
    onNavigate?: (route: Route) => void;
}

export function HostFavoritesPage({ onNavigate }: HostFavoritesPageProps) {
    const [selectedPropertyId, setSelectedPropertyId] = useState<number | null>(null);

    // Récupérer les favoris groupés par propriété
    const { data: groupedData, isLoading: groupedLoading, refetch } = useQuery({
        queryKey: ['host-favorites-grouped'],
        queryFn: () => hostService.getHostFavoritesGroupedByProperty(),
    });

    // Récupérer les statistiques
    const { data: statsData } = useQuery({
        queryKey: ['host-favorites-stats'],
        queryFn: () => hostService.getHostFavoritesStatistics(),
    });

    const properties = groupedData?.data || [];
    const stats = statsData?.data || {};

    // ✅ Fonction pour obtenir l'URL de l'image avec le bon format
    const getImageUrl = (property: any): string => {
        // Vérifier cover_photo (objet)
        if (property.cover_photo && typeof property.cover_photo === 'object') {
            if (property.cover_photo.photo_url) {
                return property.cover_photo.photo_url;
            }
            if (property.cover_photo.full_url) {
                return property.cover_photo.full_url;
            }
        }
        
        // Vérifier cover_photo (string)
        if (property.cover_photo && typeof property.cover_photo === 'string') {
            return property.cover_photo;
        }
        
        // Vérifier cover_photo_url
        if (property.cover_photo_url) {
            return property.cover_photo_url;
        }
        
        // Vérifier photos
        if (property.photos && Array.isArray(property.photos) && property.photos.length > 0) {
            const firstPhoto = property.photos[0];
            if (firstPhoto.photo_url) {
                return firstPhoto.photo_url;
            }
            if (firstPhoto.full_url) {
                return firstPhoto.full_url;
            }
            if (firstPhoto.url) {
                return firstPhoto.url;
            }
        }
        
        // Vérifier photo_url
        if (property.photo_url) {
            return property.photo_url;
        }
        
        // Vérifier image
        if (property.image) {
            return property.image;
        }
        
        // Fallback
        return '/placeholder.jpg';
    };

    // ✅ Fonction pour obtenir l'URL de l'avatar d'un utilisateur
    const getUserAvatar = (user: any): string => {
        if (user?.avatar_url) {
            return user.avatar_url;
        }
        if (user?.photo) {
            return user.photo;
        }
        return `https://ui-avatars.com/api/?background=00c9a7&color=fff&name=${encodeURIComponent(user?.name || 'User')}&bold=true&size=80`;
    };

    // ✅ Formater la date
    const formatDate = (dateString: string) => {
        const date = new Date(dateString);
        return date.toLocaleDateString('fr-FR', {
            day: 'numeric',
            month: 'long',
            year: 'numeric'
        });
    };

    const handleExport = async () => {
        try {
            const blob = await hostService.exportHostFavorites();
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `favoris_hote_${new Date().toISOString().split('T')[0]}.csv`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            window.URL.revokeObjectURL(url);
            console.log('✅ Export réussi');
        } catch (error) {
            console.error('Erreur lors de l\'export:', error);
        }
    };

    if (groupedLoading) {
        return (
            <div className="min-h-screen bg-[#f4fffe] py-10">
                <div className="max-w-[1200px] mx-auto px-4">
                    <div className="text-center py-20">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto"></div>
                        <p className="text-gray-500 mt-4">Chargement des favoris...</p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-[#f4fffe] py-10">
            <div className="max-w-[1200px] mx-auto px-4 sm:px-6 lg:px-8">
                {/* En-tête */}
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-8">
                    <div>
                        <h1 className="text-3xl font-bold text-[#0f2940]">Favoris reçus</h1>
                        <p className="text-gray-500 mt-1">
                            Voyageurs qui ont aimé vos propriétés
                        </p>
                    </div>
                    <button
                        onClick={handleExport}
                        className="bg-[#00c9a7] text-white px-4 py-2 rounded-full flex items-center gap-2 hover:bg-[#00b396] transition"
                    >
                        <Download className="w-4 h-4" />
                        Exporter
                    </button>
                </div>

                {/* Statistiques */}
                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4 mb-8">
                    <div className="bg-white rounded-2xl p-4 border border-[#e2f5f2] shadow-sm">
                        <div className="flex items-center justify-between">
                            <Heart className="w-5 h-5 text-[#00c9a7]" />
                            <span className="text-2xl font-bold text-[#0f2940]">{stats.total_favorites || 0}</span>
                        </div>
                        <p className="text-sm text-gray-500 mt-1">Total favoris</p>
                    </div>
                    <div className="bg-white rounded-2xl p-4 border border-[#e2f5f2] shadow-sm">
                        <div className="flex items-center justify-between">
                            <Users className="w-5 h-5 text-[#00c9a7]" />
                            <span className="text-2xl font-bold text-[#0f2940]">{stats.unique_travelers || 0}</span>
                        </div>
                        <p className="text-sm text-gray-500 mt-1">Voyageurs uniques</p>
                    </div>
                    <div className="bg-white rounded-2xl p-4 border border-[#e2f5f2] shadow-sm">
                        <div className="flex items-center justify-between">
                            <Home className="w-5 h-5 text-[#00c9a7]" />
                            <span className="text-2xl font-bold text-[#0f2940]">{stats.total_properties_with_favorites || 0}</span>
                        </div>
                        <p className="text-sm text-gray-500 mt-1">Propriétés avec favoris</p>
                    </div>
                    <div className="bg-white rounded-2xl p-4 border border-[#e2f5f2] shadow-sm">
                        <div className="flex items-center justify-between">
                            <TrendingUp className="w-5 h-5 text-[#00c9a7]" />
                            <span className="text-2xl font-bold text-[#0f2940]">{stats.favorites_last_30_days || 0}</span>
                        </div>
                        <p className="text-sm text-gray-500 mt-1">Derniers 30 jours</p>
                    </div>
                </div>

                {/* Graphique tendance hebdomadaire */}
                {stats.weekly_trend && stats.weekly_trend.length > 0 && (
                    <div className="bg-white rounded-2xl p-6 border border-[#e2f5f2] mb-8 shadow-sm">
                        <h3 className="font-semibold mb-4 flex items-center gap-2">
                            <Calendar className="w-4 h-4 text-[#00c9a7]" />
                            Tendance des favoris (7 derniers jours)
                        </h3>
                        <div className="flex items-end justify-between gap-2 h-32">
                            {stats.weekly_trend.map((day: any, index: number) => {
                                const maxCount = Math.max(...stats.weekly_trend.map((d: any) => d.count), 1);
                                const height = (day.count / maxCount) * 100;
                                return (
                                    <div key={index} className="flex-1 flex flex-col items-center">
                                        <div className="w-full relative">
                                            <div 
                                                className="w-full bg-[#00c9a7]/20 rounded-t-lg transition-all hover:bg-[#00c9a7]/40"
                                                style={{ height: `${height}%`, minHeight: '4px' }}
                                            >
                                                {day.count > 0 && (
                                                    <div className="text-center text-xs font-medium text-[#00c9a7] relative -top-5">
                                                        {day.count}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                        <span className="text-xs text-gray-500 mt-2">{day.day}</span>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                {/* Liste des propriétés avec favoris */}
                <div className="space-y-6">
                    {properties.length === 0 ? (
                        <div className="bg-white rounded-3xl border border-[#e2f5f2] p-12 text-center shadow-sm">
                            <Heart className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                            <h3 className="text-xl font-semibold text-[#0f2940] mb-2">
                                Aucun favori pour le moment
                            </h3>
                            <p className="text-gray-500">
                                Les voyageurs n'ont pas encore ajouté vos propriétés en favoris.
                            </p>
                        </div>
                    ) : (
                        properties.map((property: any) => {
                            const imageUrl = getImageUrl(property);
                            const isExpanded = selectedPropertyId === property.id;
                            
                            return (
                                <div key={property.id} className="bg-white rounded-2xl border border-[#e2f5f2] overflow-hidden shadow-sm">
                                    {/* En-tête propriété */}
                                    <div 
                                        className="p-4 bg-[#f4fffe] border-b border-[#e2f5f2] cursor-pointer hover:bg-[#e8f5f2] transition"
                                        onClick={() => setSelectedPropertyId(isExpanded ? null : property.id)}
                                    >
                                        <div className="flex items-center gap-4">
                                            {/* Image de la propriété */}
                                            <div className="w-16 h-16 rounded-lg overflow-hidden bg-gray-100 flex-shrink-0">
                                                {imageUrl && imageUrl !== '/placeholder.jpg' ? (
                                                    <img 
                                                        src={imageUrl} 
                                                        alt={property.title}
                                                        className="w-full h-full object-cover"
                                                        onError={(e) => {
                                                            (e.target as HTMLImageElement).src = '/placeholder.jpg';
                                                        }}
                                                    />
                                                ) : (
                                                    <div className="w-full h-full flex items-center justify-center">
                                                        <Home className="w-8 h-8 text-gray-400" />
                                                    </div>
                                                )}
                                            </div>
                                            
                                            <div className="flex-1">
                                                <h3 className="font-semibold text-[#0f2940]">{property.title}</h3>
                                                <p className="text-sm text-gray-500">
                                                    📍 {property.district}, {property.city}
                                                </p>
                                                <div className="flex items-center gap-3 mt-1">
                                                    <div className="flex items-center gap-1">
                                                        <Heart className="w-4 h-4 text-[#00c9a7]" />
                                                        <span className="text-sm font-medium text-[#00c9a7]">
                                                            {property.favorites_count} favoris
                                                        </span>
                                                    </div>
                                                    <button
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            onNavigate?.({ name: 'listing', id: property.id.toString() });
                                                        }}
                                                        className="text-xs text-blue-500 hover:text-blue-700 flex items-center gap-1"
                                                    >
                                                        <Eye className="w-3 h-3" />
                                                        Voir l'annonce
                                                    </button>
                                                </div>
                                            </div>
                                            <div className="text-gray-400 text-lg">
                                                {isExpanded ? '▲' : '▼'}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Liste des voyageurs qui ont favorisé */}
                                    {isExpanded && property.favorites && property.favorites.length > 0 && (
                                        <div className="divide-y divide-[#e2f5f2]">
                                            {property.favorites.map((favorite: any) => (
                                                <div key={favorite.id} className="p-4 hover:bg-[#f4fffe] transition">
                                                    <div className="flex items-start gap-4">
                                                        {/* Avatar du voyageur */}
                                                        <div className="flex-shrink-0">
                                                            {favorite.user_avatar || favorite.user?.avatar_url ? (
                                                                <img 
                                                                    src={favorite.user_avatar || favorite.user?.avatar_url}
                                                                    alt={favorite.user_name || favorite.user?.name}
                                                                    className="w-10 h-10 rounded-full object-cover"
                                                                    onError={(e) => {
                                                                        (e.target as HTMLImageElement).src = getUserAvatar(favorite.user);
                                                                    }}
                                                                />
                                                            ) : (
                                                                <div className="w-10 h-10 rounded-full bg-gray-200 flex items-center justify-center">
                                                                    <User className="w-5 h-5 text-gray-400" />
                                                                </div>
                                                            )}
                                                        </div>
                                                        
                                                        <div className="flex-1">
                                                            <div className="flex items-center justify-between flex-wrap gap-2">
                                                                <h4 className="font-medium text-[#0f2940]">
                                                                    {favorite.user_name || favorite.user?.name || 'Voyageur'}
                                                                </h4>
                                                                <span className="text-xs text-gray-400">
                                                                    Ajouté le {formatDate(favorite.created_at)}
                                                                </span>
                                                            </div>
                                                            
                                                            {favorite.user_email && (
                                                                <p className="text-sm text-gray-500 mt-1">
                                                                    ✉️ {favorite.user_email}
                                                                </p>
                                                            )}
                                                            
                                                            {favorite.user_phone && (
                                                                <p className="text-sm text-gray-500">
                                                                    📞 {favorite.user_phone}
                                                                </p>
                                                            )}
                                                            
                                                            {favorite.notes && (
                                                                <p className="text-sm text-gray-600 mt-2 italic bg-gray-50 p-2 rounded-lg">
                                                                    "📝 {favorite.notes}"
                                                                </p>
                                                            )}
                                                            
                                                            <div className="flex gap-2 mt-3">
                                                                {favorite.user_id && (
                                                                    <button
                                                                        onClick={() => onNavigate?.({ name: 'profile', id: favorite.user_id.toString() })}
                                                                        className="text-xs border border-[#00c9a7] text-[#00c9a7] px-3 py-1 rounded-full hover:bg-[#00c9a7] hover:text-white transition"
                                                                    >
                                                                        Voir profil
                                                                    </button>
                                                                )}
                                                                {favorite.user_id && (
                                                                    <button
                                                                        onClick={() => onNavigate?.({ name: 'host-messages', id: favorite.user_id.toString() })}
                                                                        className="text-xs border border-gray-300 text-gray-600 px-3 py-1 rounded-full hover:bg-gray-100 transition flex items-center gap-1"
                                                                    >
                                                                        <MessageCircle className="w-3 h-3" />
                                                                        Envoyer message
                                                                    </button>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                    
                                    {/* Message si aucun favori pour cette propriété */}
                                    {isExpanded && (!property.favorites || property.favorites.length === 0) && (
                                        <div className="p-8 text-center text-gray-500">
                                            <Heart className="w-12 h-12 text-gray-300 mx-auto mb-2" />
                                            <p>Aucun voyageur n'a encore ajouté cette propriété en favoris.</p>
                                        </div>
                                    )}
                                </div>
                            );
                        })
                    )}
                </div>
            </div>
        </div>
    );
}
// ==================== MESSAGES PAGE ====================


interface MessagesPageProps {
  onNavigate?: (route: any) => void;
  id?: string;
  search?: string;
}

// ============================================
// COMPOSANT CHAT VIEW
// ============================================
const MessagesChatView = ({ 
  conversation,
  messages, 
  messagesLoading, 
  user, 
  onSendMessage,
  isSending,
  onBack,
  hostName,
  propertyTitle,
  isInquiry
}: { 
  conversation: any;
  messages: any[];
  messagesLoading: boolean;
  user: any;
  onSendMessage: (message: string) => void;
  isSending: boolean;
  onBack?: () => void;
  hostName: string;
  propertyTitle: string;
  isInquiry: boolean;
}) => {
  const [messageInput, setMessageInput] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  console.log('💬 MessagesChatView - messages:', messages);
  console.log('💬 MessagesChatView - conversation:', conversation);

  useEffect(() => {
    setTimeout(() => {
      scrollToEnd(messagesEndRef.current);
    }, 100);
  }, [messages]);

  if (!conversation) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-gray-400 p-4">
        <MessageCircle className="w-16 h-16 mb-4 opacity-50" />
        <p className="text-lg font-medium text-center">Sélectionnez une conversation</p>
        <p className="text-sm text-center">Les messages apparaissent ici</p>
      </div>
    );
  }

  const handleSend = () => {
    if (!messageInput.trim()) return;
    onSendMessage(messageInput.trim());
    setMessageInput('');
    if (textareaRef.current) {
      textareaRef.current.style.height = '44px';
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleTextareaChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setMessageInput(e.target.value);
    const textarea = e.target;
    textarea.style.height = '44px';
    textarea.style.height = Math.min(textarea.scrollHeight, 120) + 'px';
  };

  const displayName = hostName || 'Hôte';
  const displayTitle = propertyTitle || 'Conversation';

  return (
    <div className="flex flex-col h-full bg-white">
      {/* En-tête */}
    
<div className="p-3 sm:p-4 border-b bg-white flex-shrink-0">
  <div className="flex items-center gap-3">
    {onBack && (
      <button 
        onClick={onBack}
        className="lg:hidden p-2 -ml-2 rounded-full hover:bg-gray-100 transition"
      >
        <ArrowLeft className="w-5 h-5 text-gray-600" />
      </button>
    )}
    <div className="w-10 h-10 rounded-full bg-[#00c9a7] flex items-center justify-center text-white font-bold flex-shrink-0 text-sm">
      {displayName.charAt(0).toUpperCase()}
    </div>
    <div className="flex-1 min-w-0">
      <p className="font-semibold text-gray-900 truncate">{displayName}</p>
      <div className="flex items-center gap-1 text-xs text-gray-500 truncate">
        {isInquiry ? (
          <>
            <Sparkles className="w-3 h-3 flex-shrink-0 text-[#00c9a7]" />
            <span className="truncate">{displayTitle}</span>
            <span className="flex-shrink-0 text-[#00c9a7]">· Demande</span>
            {conversation.booking?.date && (
              <span className="flex-shrink-0 text-gray-400">· {new Date(conversation.booking.date).toLocaleDateString('fr-FR')}</span>
            )}
          </>
        ) : (
          <span className="truncate">{displayTitle}</span>
        )}
      </div>
    </div>
    {conversation.booking?.host?.phone && (
      <a href={`tel:${conversation.booking.host.phone}`} className="p-2 rounded-full hover:bg-gray-100 transition flex-shrink-0">
        <Phone className="w-4 h-4 text-gray-500" />
      </a>
    )}
  </div>
  {/* ✅ Afficher les détails du service si présent */}
  {conversation.booking?.service_id && (
    <div className="mt-2 p-2 bg-gray-50 rounded-lg border border-gray-100">
      <div className="flex items-center gap-2 text-xs text-gray-600">
        <Briefcase className="w-3 h-3 text-[#00c9a7]" />
        <span className="font-medium">Service:</span>
        <span>{conversation.booking.service_name || 'Service'}</span>
        {conversation.booking.location && (
          <>
            <span className="text-gray-300">|</span>
            <MapPin className="w-3 h-3" />
            <span>{conversation.booking.location}</span>
          </>
        )}
        {conversation.booking.price && (
          <>
            <span className="text-gray-300">|</span>
            <span className="font-medium text-[#00c9a7]">{conversation.booking.price} FCFA</span>
          </>
        )}
      </div>
    </div>
  )}
</div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-3 sm:p-4 space-y-3 bg-gray-50">
        {messagesLoading ? (
          <div className="text-center py-10">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-[#00c9a7] mx-auto"></div>
            <p className="text-gray-500 mt-2 text-sm">Chargement des messages...</p>
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-10 text-gray-400">
            <MessageCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
            <p className="text-sm">Aucun message</p>
            <p className="text-xs mt-1">Soyez le premier à envoyer un message !</p>
          </div>
        ) : (
          messages.map((msg: any, index: number) => {
            const isFromMe = msg.sender_id === user?.id || msg.is_from_me === true || msg.is_from_me === 1;
            
            return (
              <div key={msg.id || index} className={`flex ${isFromMe ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] sm:max-w-[70%] rounded-2xl p-3 ${
                  isFromMe ? 'bg-[#00c9a7] text-white' : 'bg-white text-gray-800 shadow-sm'
                }`}>
                  <p className="text-sm sm:text-base whitespace-pre-wrap break-words">{msg.message}</p>
                  <p className={`text-xs mt-1 ${isFromMe ? 'text-white/70' : 'text-gray-400'}`}>
                    {messageTime(msg.created_at)}
                  </p>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Zone de saisie */}
      <div className="p-2 sm:p-4 border-t bg-white flex-shrink-0">
        <div className="flex gap-2 items-end">
          <textarea
            ref={textareaRef}
            value={messageInput}
            onChange={handleTextareaChange}
            onKeyPress={handleKeyPress}
            placeholder={`Écrire à ${displayName}...`}
            rows={1}
            className="flex-1 border rounded-full px-3 sm:px-4 py-2 sm:py-2.5 focus:outline-none focus:ring-2 focus:ring-[#00c9a7] resize-none text-sm sm:text-base"
            style={{ 
              minHeight: '40px', 
              maxHeight: '100px',
              lineHeight: '1.5'
            }}
            disabled={isSending}
          />
          <button
            onClick={handleSend}
            disabled={!messageInput.trim() || isSending}
            className="bg-[#00c9a7] text-white rounded-full p-2.5 sm:p-3 disabled:opacity-50 hover:bg-[#00b89a] transition flex-shrink-0"
          >
            {isSending ? (
              <div className="animate-spin rounded-full h-4 w-4 sm:h-5 sm:w-5 border-b-2 border-white" />
            ) : (
              <Send className="w-4 h-4 sm:w-5 sm:h-5" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};


// ============================================
// COMPOSANT PRINCIPAL
// ============================================
export function MessagesPage({ onNavigate, id, search }: MessagesPageProps) {
  const { user, isAuthenticated } = useAuth();
  const location = useLocation();
  const queryClient = useQueryClient();

  // États pour les paramètres d'inquiry
  const [inquiryExperienceId, setInquiryExperienceId] = useState<string | null>(null);
  const [inquiryHostId, setInquiryHostId] = useState<string | null>(null);
  const [inquiryHostName, setInquiryHostName] = useState<string | null>(null);
  const [inquiryExperienceName, setInquiryExperienceName] = useState<string | null>(null);
  const [inquiryCheckIn, setInquiryCheckIn] = useState<string | null>(null);
  const [inquiryCheckOut, setInquiryCheckOut] = useState<string | null>(null);
  const [inquiryParticipants, setInquiryParticipants] = useState<string | null>(null);
  const [inquiryDates, setInquiryDates] = useState<string[]>([]);

  // États du composant
  const [selectedConversation, setSelectedConversation] = useState<any | null>(null);
  const [hasSentInquiry, setHasSentInquiry] = useState(false);
  const [isSendingInquiry, setIsSendingInquiry] = useState(false);
  const [selectedType, setSelectedType] = useState<'booking' | 'inquiry'>('booking');
  const [selectedId, setSelectedId] = useState<string | number | null>(null);
  const [messageInput, setMessageInput] = useState('');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const initialMessageSent = useRef(false);

  // Récupération des paramètres depuis l'URL
  useEffect(() => {
    // ... votre code existant ...
  }, [search, location.search, location.pathname, id]);

  // Récupération des conversations
  const { data: conversationsData, isLoading: convLoading, refetch: refetchConversations } = useQuery({
    queryKey: ['conversations'],
    queryFn: async () => {
      // Chargements indépendants : auparavant, l'échec des demandes avant
      // réservation (route alors inexistante) vidait TOUTE la liste, y
      // compris les conversations de réservation (« Conversations (0) »).
      const [bookingsResult, inquiriesResult] = await Promise.allSettled([
        messageService.getConversations(),
        messageService.getInquiries(),
      ]);
      const bookings = bookingsResult.status === 'fulfilled' ? bookingsResult.value?.data || [] : [];
      const inquiries = inquiriesResult.status === 'fulfilled' ? inquiriesResult.value?.data || [] : [];
      // Demandes (datées) d'abord, par date ; puis les réservations.
      const sortedInquiries = [...inquiries].sort((a: any, b: any) => String(b.updated_at || '').localeCompare(String(a.updated_at || '')));
      return { data: [...sortedInquiries, ...bookings] };
    },
    enabled: isAuthenticated,
  });
  const conversations = conversationsData?.data || [];

  // Lien « Discutez avec l'hôte » depuis une annonce : /messages/inquiry?property=ID.
  // Cette page ne savait ouvrir que les demandes de service : on arrivait sur
  // « Sélectionnez une conversation », sans pouvoir écrire.
  const propertyParam = new URLSearchParams(String(search || location.search || '').replace(/^\?/, '')).get('property');
  useEffect(() => {
    if (!propertyParam || !isAuthenticated || selectedConversation) return;
    let cancelled = false;
    propertyService.getById(Number(propertyParam))
      .then((res: any) => {
        const p = res?.data?.data || res?.data || res;
        const hostId = p?.user?.id ?? p?.user_id;
        if (cancelled || !hostId) return;
        const existing = conversations.find((c: any) => c.type === 'inquiry' && c.booking?.host?.id === hostId);
        const hostName = p?.user ? (p.user.full_name || `${p.user.first_name ?? ''} ${p.user.last_name ?? ''}`.trim()) : 'Hôte';
        const conv = existing ?? {
          type: 'inquiry',
          booking: { id: null, reference: '', host: { id: hostId, name: hostName, photo: null }, property: { id: p.id, title: p.title, photo: null }, dates: null },
          last_message: null,
          unread_count: 0,
        };
        setSelectedConversation({ ...conv, booking: { ...conv.booking, property: { ...(conv.booking.property || {}), id: p.id, title: p.title } } });
        setSelectedType('inquiry');
        setSelectedId(hostId);
      })
      .catch(() => toast.error('Impossible d’ouvrir la conversation avec l’hôte.'));
    return () => { cancelled = true; };
  }, [propertyParam, isAuthenticated, conversations.length]); // eslint-disable-line react-hooks/exhaustive-deps

  // Mutations
  // Dans MessagesPage - inquiryMutation

const inquiryMutation = useMutation({
  mutationFn: (data: any) => {
    // ✅ Vérifier si c'est une demande pour un service
    const inquiryType = localStorage.getItem('inquiry_type') || 'experience';
    
    if (inquiryType === 'service') {
      // ✅ Pour les services, utiliser sendInquiry avec les données du service
      const serviceId = localStorage.getItem('current_service_id');
      return messageService.sendInquiry({
        ...data,
        service_id: parseInt(serviceId || '0'),
        inquiry_type: 'service'
      });
    }
    
    // ✅ Pour les expériences (comportement normal)
    return messageService.sendInquiry(data);
  },
  onSuccess: (response) => {
    console.log('✅ Premier message envoyé avec succès:', response);
    setHasSentInquiry(true);
    setIsSendingInquiry(false);
    initialMessageSent.current = true;
    localStorage.removeItem('pendingInquiry');
    localStorage.removeItem('inquiry_type');
    localStorage.removeItem('current_service_id');
    toast.success('Message envoyé au prestataire');
    
    setTimeout(() => {
      refetchConversations();
      queryClient.invalidateQueries({ queryKey: ['conversations'] });
    }, 1000);
  },
  onError: (err: any) => {
    console.error('❌ Erreur inquiry:', err);
    setIsSendingInquiry(false);
    toast.error(err?.response?.data?.message || 'Erreur lors de l\'envoi');
  },
});

  const sendBookingMessageMutation = useMutation({
    mutationFn: ({ bookingId, message }: { bookingId: number; message: string }) => {
      console.log('📤 sendBookingMessage - bookingId:', bookingId);
      return messageService.sendMessage(bookingId, { message });
    },
    onSuccess: () => {
      console.log('✅ Message booking envoyé');
      setMessageInput('');
      refetchMessages();
      queryClient.invalidateQueries({ queryKey: ['conversations'] });
    },
    onError: (err: any) => {
      console.error('❌ Erreur envoi booking:', err);
      toast.error(err?.response?.data?.message || 'Erreur lors de l\'envoi');
    },
  });

  const sendInquiryReplyMutation = useMutation({
    mutationFn: ({ hostId, message, propertyId }: { hostId: number; message: string; propertyId?: number | null }) => {
      return messageService.sendInquiryReply(hostId, { message, property_id: propertyId ?? undefined });
    },
    onSuccess: () => {
      console.log('✅ Message inquiry envoyé');
      setMessageInput('');
      refetchMessages();
      queryClient.invalidateQueries({ queryKey: ['conversations'] });
    },
    onError: (err: any) => {
      console.error('❌ Erreur envoi inquiry:', err);
      toast.error(err?.response?.data?.message || 'Erreur lors de l\'envoi');
    },
  });

  // ✅ Récupération des messages - CORRIGÉ
  const { data: messagesData, refetch: refetchMessages, isLoading: messagesLoading } = useQuery({
    queryKey: ['messages', selectedType, selectedId],
    queryFn: async () => {
      if (!selectedId) {
        console.log('⏭️ Pas de selectedId, retour vide');
        return { data: { messages: [] } };
      }
      console.log('📥 Récupération messages - type:', selectedType, 'id:', selectedId);
      
      if (selectedType === 'booking') {
        const res = await messageService.getMessages(selectedId as number);
        console.log('📥 Messages booking:', res);
        return res.data;
      } else if (selectedType === 'inquiry') {
        try {
          const res = await messageService.getInquiryMessages(selectedId as number);
          console.log('📥 Messages inquiry:', res);
          return res.data;
        } catch (err: any) {
          console.error('❌ Erreur getInquiryMessages:', err);
          if (err.response?.status === 500) {
            const pendingMessages = messageService.getPendingInquiryMessages(selectedId as number);
            return { data: { host: { id: selectedId }, messages: pendingMessages } };
          }
          throw err;
        }
      }
      return { data: { messages: [] } };
    },
    enabled: !!selectedId && !!selectedType && isAuthenticated,
  });

  // ✅ Extraire les messages correctement
  const getMessages = () => {
    if (!messagesData) return [];
    if (messagesData.messages) return messagesData.messages;
    if (messagesData.data && messagesData.data.messages) return messagesData.data.messages;
    return [];
  };

  const messages = getMessages();

  // Ouvrir un fil le marque lu côté serveur : on rafraîchit la liste pour
  // retirer la pastille « non lu » sans attendre un rechargement.
  useEffect(() => {
    if (selectedId && messagesData) queryClient.invalidateQueries({ queryKey: ['conversations'] });
  }, [selectedId, messages.length]); // eslint-disable-line react-hooks/exhaustive-deps

  // Envoi automatique du premier message
  useEffect(() => {
    if (id === 'inquiry' && inquiryHostId && inquiryExperienceId && !hasSentInquiry && !isSendingInquiry && !initialMessageSent.current && isAuthenticated) {
      setIsSendingInquiry(true);
      
      let message = `Bonjour, je suis intéressé(e) par votre expérience "${inquiryExperienceName || 'proposée'}"`;
      
      if (inquiryDates && inquiryDates.length > 0) {
        message += ` pour les dates suivantes : ${inquiryDates.join(', ')}`;
      } else if (inquiryCheckIn && inquiryCheckOut) {
        message += ` du ${inquiryCheckIn} au ${inquiryCheckOut}`;
      }
      
      if (inquiryParticipants && parseInt(inquiryParticipants) > 0) {
        message += ` pour ${inquiryParticipants} personne(s)`;
      }
      
      message += `. Pourriez-vous me donner plus d'informations ? Merci !`;

      const mutationData: any = { 
        experience_id: parseInt(inquiryExperienceId, 10), 
        message 
      };
      
      if (inquiryCheckIn && inquiryCheckOut) {
        mutationData.check_in = inquiryCheckIn;
        mutationData.check_out = inquiryCheckOut;
      }
      
      if (inquiryParticipants && parseInt(inquiryParticipants) > 0) {
        mutationData.guests = parseInt(inquiryParticipants, 10);
      }
      
      inquiryMutation.mutate(mutationData);
    }
  }, [id, inquiryHostId, inquiryExperienceId, inquiryExperienceName, inquiryCheckIn, inquiryCheckOut, inquiryParticipants, inquiryDates, hasSentInquiry, isSendingInquiry, isAuthenticated]);

  // ✅ Sélection auto après envoi inquiry - CORRIGÉ
  useEffect(() => {
    if (hasSentInquiry && conversations.length > 0 && !selectedConversation && inquiryHostId) {
      const matched = conversations.find((conv: any) => {
        if (conv.type === 'inquiry' || conv.type === 'experience') {
          return conv.booking.host?.id?.toString() === inquiryHostId;
        }
        return false;
      });
      if (matched) {
        console.log('✅ Sélection auto de la conversation:', matched);
        handleSelectConversation(matched);
      }
    }
  }, [hasSentInquiry, conversations, selectedConversation, inquiryHostId]);

  // Sélection par id dans l'URL
  useEffect(() => {
    if (!selectedConversation && id && id !== 'inquiry' && conversations.length > 0) {
      const matched = conversations.find((conv: any) => conv.booking.id?.toString() === id);
      if (matched) {
        handleSelectConversation(matched);
      }
    }
  }, [id, conversations, selectedConversation]);

  // Auto-scroll
  useEffect(() => {
    scrollToEnd(messagesEndRef.current);
  }, [messages]);

  // Dans MessagesPage - useEffect pour détecter les paramètres de service

// ✅ Récupérer les paramètres depuis l'URL
useEffect(() => {
  const urlSearch = search || location.search;
  const params = new URLSearchParams(urlSearch.startsWith('?') ? urlSearch.substring(1) : urlSearch);
  
  // ✅ Détecter si c'est une demande pour un service
  const serviceId = params.get('service');
  const serviceName = params.get('service_name');
  const hostId = params.get('host_id');
  const hostName = params.get('host_name');
  const inquiryType = params.get('inquiry_type');
  const date = params.get('date');
  const locationParam = params.get('location');
  const priceParam = params.get('price');

  console.log('🔍 Paramètres détectés:', { serviceId, serviceName, hostId, hostName, inquiryType, date });

  // ✅ Si c'est une demande pour un service, créer une conversation temporaire
  if (serviceId && hostId && inquiryType === 'service') {
    console.log('💬 Demande de service détectée:', { serviceId, serviceName, hostId });
    
    // ✅ Créer une conversation virtuelle pour le service
    const tempConversation = {
      type: 'service-inquiry',
      booking: {
        host: {
          id: parseInt(hostId),
          name: hostName || 'Prestataire'
        },
        property: {
          title: serviceName || 'Service'
        },
        service_id: parseInt(serviceId),
        service_name: serviceName || 'Service',
        date: date || '',
        location: locationParam || '',
        price: priceParam || ''
      },
      last_message: {
        message: `Demande de renseignements pour le service "${serviceName || 'Service'}"`,
        sent_at: new Date().toISOString()
      },
      unread_count: 0
    };

    // ✅ Sélectionner automatiquement cette conversation
    if (!selectedConversation) {
      console.log('✅ Sélection automatique de la conversation service');
      setSelectedConversation(tempConversation);
      setSelectedType('inquiry');
      setSelectedId(parseInt(hostId));
      
      // ✅ Marquer comme une demande de service
      localStorage.setItem('current_inquiry_type', 'service');
      localStorage.setItem('current_service_id', serviceId);
      
      // ✅ Forcer le rechargement des messages
      setTimeout(() => {
        refetchMessages();
      }, 300);
    }
  }
}, [search, location.search, location.pathname]);

// Dans MessagesPage - useEffect pour récupérer les données sauvegardées

useEffect(() => {
    // ✅ Vérifier s'il y a des données d'inquiry sauvegardées
    const inquiryDataStr = localStorage.getItem('inquiry_data');
    if (inquiryDataStr) {
        try {
            const inquiryData = JSON.parse(inquiryDataStr);
            console.log('📦 Données inquiry sauvegardées trouvées:', inquiryData);
            
            // ✅ Si c'est un service
            if (inquiryData.service_id) {
                const tempConversation = {
                    type: 'service-inquiry',
                    booking: {
                        host: {
                            id: inquiryData.host_id ? parseInt(inquiryData.host_id) : 0,
                            name: inquiryData.host_name || 'Prestataire'
                        },
                        property: {
                            title: inquiryData.service_title || 'Service'
                        },
                        service_id: parseInt(inquiryData.service_id),
                        service_name: inquiryData.service_title || 'Service',
                        date: inquiryData.date || '',
                        location: inquiryData.location || '',
                        price: inquiryData.price || ''
                    },
                    last_message: {
                        message: `Demande de renseignements pour le service "${inquiryData.service_title || 'Service'}"`,
                        sent_at: new Date().toISOString()
                    },
                    unread_count: 0
                };
                
                if (!selectedConversation) {
                    console.log('✅ Sélection automatique de la conversation service (après connexion)');
                    setSelectedConversation(tempConversation);
                    setSelectedType('inquiry');
                    setSelectedId(inquiryData.host_id ? parseInt(inquiryData.host_id) : 0);
                    
                    setTimeout(() => {
                        refetchMessages();
                    }, 300);
                }
            }
        } catch (e) {
            console.error('❌ Erreur parsing inquiry_data:', e);
        }
    }
}, []);

  // ✅ handleSelectConversation - CORRIGÉ avec logs
  const handleSelectConversation = (conv: any) => {
    console.log('📌 Sélection conversation:', conv);
    console.log('📌 Type de conversation:', conv.type);
    console.log('📌 Host:', conv.booking.host);
    
    if (conv.type === 'inquiry' || conv.type === 'experience') {
      // ✅ Pour les conversations sans réservation - utiliser host.id
      setSelectedType('inquiry');
      const hostId = conv.booking.host?.id;
      if (hostId) {
        setSelectedId(hostId);
        setSelectedConversation(conv);
        setMobileMenuOpen(false);
        console.log('✅ Sélection inquiry - hostId:', hostId);
        
        // ✅ Forcer le rechargement des messages
        setTimeout(() => {
          refetchMessages();
        }, 200);
      } else {
        console.error('❌ Host ID manquant');
        toast.error('Impossible de charger la conversation');
      }
    } else {
      // ✅ Pour les conversations avec réservation - utiliser booking.id
      setSelectedType('booking');
      const bookingId = conv.booking?.id;
      if (bookingId) {
        setSelectedId(bookingId);
        setSelectedConversation(conv);
        setMobileMenuOpen(false);
        console.log('✅ Sélection booking - bookingId:', bookingId);
        
        // ✅ Forcer le rechargement des messages
        setTimeout(() => {
          refetchMessages();
        }, 200);
      } else {
        console.error('❌ Booking ID manquant');
        toast.error('Impossible de charger la conversation');
      }
    }
  };

  // ✅ handleSendMessage - CORRIGÉ
  const handleSendMessage = (message: string) => {
    if (!selectedConversation) {
      toast.error('Sélectionnez une conversation');
      return;
    }
    
    console.log('📤 Envoi message - selectedType:', selectedType);
    console.log('📤 Envoi message - selectedId:', selectedId);
    
    const isInquiry = selectedConversation.type === 'inquiry' || 
                      selectedConversation.type === 'experience' ||
                      selectedType === 'inquiry';
    
    if (isInquiry) {
      const hostId = selectedConversation.booking.host?.id;
      if (!hostId) {
        toast.error('ID de l\'hôte introuvable');
        return;
      }
      sendInquiryReplyMutation.mutate({ hostId, message, propertyId: selectedConversation.booking.property?.id ?? null });
    } else {
      const bookingId = selectedConversation.booking?.id;
      if (!bookingId) {
        toast.error('ID de réservation invalide');
        return;
      }
      console.log('📤 Envoi booking à bookingId:', bookingId);
      sendBookingMessageMutation.mutate({ bookingId, message });
    }
  };

  // ============================================
  // AFFICHAGE
  // ============================================

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-4 border-[#00c9a7] border-t-transparent mx-auto mb-4"></div>
          <p className="text-gray-500">Redirection vers la connexion...</p>
        </div>
      </div>
    );
  }

  if (id === 'inquiry' && inquiryHostId && inquiryExperienceId && isSendingInquiry) {
    return (
      <div className="bg-[#f4fffe] min-h-screen py-10">
        <div className="max-w-[1200px] mx-auto px-4 text-center py-20">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto mb-4"></div>
          <p className="text-gray-600">Envoi de votre message à l'hôte...</p>
        </div>
      </div>
    );
  }

  if (convLoading) {
    return (
      <div className="bg-[#f4fffe] min-h-screen py-10">
        <div className="max-w-[1200px] mx-auto px-4 text-center py-20">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#00c9a7] mx-auto"></div>
          <p className="text-gray-600 mt-4">Chargement des conversations...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#f4fffe] min-h-screen py-4 sm:py-10">
      <div className="max-w-[1200px] mx-auto px-3 sm:px-4 lg:px-8">
        <div className="flex justify-between items-center mb-4 sm:mb-6">
          <h1 className="text-xl sm:text-2xl font-bold text-[#0F2940] flex items-center gap-2">
            <MessageCircle className="w-5 h-5 sm:w-6 sm:h-6 text-[#00c9a7]" />
            <span className="hidden sm:inline">Messagerie</span>
            <span className="sm:hidden">Messages</span>
          </h1>
          <button onClick={() => onNavigate?.({ name: 'home' })} className="text-sm text-gray-500 hover:text-[#00c9a7] transition">← Retour</button>
        </div>

        <div className="flex flex-col lg:flex-row gap-4 sm:gap-6 bg-white rounded-2xl sm:rounded-3xl shadow-md overflow-hidden border border-[#e2f5f2]">
          
          {/* Liste des conversations */}
          {/* Sur mobile : la liste s'affiche d'office tant qu'aucune conversation
              n'est ouverte (elle était cachée derrière un bouton ☰ et l'écran
              n'affichait que « Sélectionnez une conversation »). */}
          <div className={`
            ${mobileMenuOpen || !selectedConversation ? 'block' : 'hidden'} 
            lg:block lg:w-1/3 border-r
            ${mobileMenuOpen ? 'fixed inset-0 z-50 bg-white p-4 overflow-y-auto' : ''}
          `}>
            {mobileMenuOpen && (
              <button 
                onClick={() => setMobileMenuOpen(false)}
                className="lg:hidden absolute top-4 right-4 p-2 rounded-full hover:bg-gray-100"
              >
                <X className="w-5 h-5 text-gray-600" />
              </button>
            )}
            
            <div className={`p-3 sm:p-4 border-b font-semibold bg-white flex justify-between items-center ${mobileMenuOpen ? 'mt-12' : ''}`}>
              <span>Conversations ({conversations.length})</span>
              <button 
                onClick={() => refetchConversations()} 
                className="text-xs text-[#00c9a7] hover:underline flex items-center gap-1"
              >
                <RefreshCw className="w-4 h-4" />
                <span className="hidden sm:inline">Rafraîchir</span>
              </button>
            </div>
            
            <div className="divide-y max-h-[calc(100vh-200px)] overflow-y-auto">
              {conversations.length === 0 ? (
                <div className="p-8 text-center text-gray-400">
                  <MessageCircle className="w-12 h-12 mx-auto mb-2 opacity-50" />
                  <p>Aucune conversation</p>
                  <p className="text-sm mt-1">Contactez un hôte pour commencer</p>
                </div>
              ) : (
                conversations.map((conv: any, index: number) => {
                  const isSelected = selectedConversation === conv;
                  const isInquiry = conv.type === 'inquiry' || conv.type === 'experience';
                  const guestName = conv.booking.host?.name || 'Hôte';
                  const propertyTitle = conv.booking.property?.title || 
                                        conv.booking.experience_name || 
                                        'Demande d\'information';
                  
                  return (
                    <button
                      key={index}
                      onClick={() => handleSelectConversation(conv)}
                      className={`w-full text-left p-3 sm:p-4 hover:bg-gray-50 transition ${
                        isSelected ? 'bg-gray-100' : ''
                      }`}
                    >
                      <div className="flex justify-between items-start">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="font-medium text-gray-900 text-sm sm:text-base truncate">
                              {guestName}
                            </p>
                            {conv.unread_count > 0 && (
                              <span className="bg-red-500 text-white text-xs rounded-full px-2 py-0.5 flex-shrink-0">
                                {conv.unread_count}
                              </span>
                            )}
                          </div>
                          <p className="text-xs sm:text-sm text-gray-500 truncate">{propertyTitle}</p>
                          {isInquiry && (
                            <span className="text-[10px] text-[#00c9a7] mt-0.5 inline-block">✉️ Demande d'information</span>
                          )}
                          {conv.booking.dates?.check_in && conv.booking.dates?.check_out && (
                            <p className="text-xs text-gray-400 mt-0.5">
                              📅 {conv.booking.dates.check_in} → {conv.booking.dates.check_out}
                            </p>
                          )}
                        </div>
                        {conv.last_message && (
                          <span className="text-[10px] sm:text-xs text-gray-400 flex-shrink-0 ml-2">
                            {conv.last_message.sent_at}
                          </span>
                        )}
                      </div>
                      {conv.last_message && (
                        <p className="text-xs text-gray-400 mt-2 truncate">
                          {conv.last_message.message}
                        </p>
                      )}
                    </button>
                  );
                })
              )}
            </div>
          </div>

          {/* Zone de chat */}
          <div className={`${selectedConversation ? 'flex' : 'hidden lg:flex'} lg:w-2/3 flex-col h-[calc(100dvh-13rem)] min-h-[420px] lg:h-[600px] relative`}>
            <button 
              onClick={() => setMobileMenuOpen(true)}
              className="lg:hidden absolute top-3 left-3 z-10 p-2 rounded-full bg-white shadow-md hover:bg-gray-50"
            >
              <Menu className="w-5 h-5 text-gray-600" />
            </button>

            {selectedConversation ? (
              <MessagesChatView 
                conversation={selectedConversation}
                messages={messages}
                messagesLoading={messagesLoading}
                user={user}
                onSendMessage={handleSendMessage}
                isSending={sendBookingMessageMutation.isPending || sendInquiryReplyMutation.isPending}
                onBack={() => setMobileMenuOpen(true)}
                hostName={selectedConversation.booking.host?.name || 'Hôte'}
                propertyTitle={selectedConversation.booking.property?.title || 
                               selectedConversation.booking.experience_name || 
                               'Demande d\'information'}
                isInquiry={selectedConversation.type === 'inquiry' || selectedConversation.type === 'experience'}
              />
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
                <MessageCircle className="w-16 h-16 mb-4 opacity-50" />
                <p className="text-lg font-medium">Sélectionnez une conversation</p>
                <p className="text-sm">Ou contactez un hôte depuis une expérience</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
// ==================== FAVORITES PAGE ====================

export function FavoritesPage({ onNavigate }: PageProps) {
  const { favorites, removeFavorite, toggleFavorite } = useFavorites();
  const [selectedFilter, setSelectedFilter] = useState('Tous');
  const [isLoading, setIsLoading] = useState(true);

  // ✅ Simuler un chargement rapide
  useEffect(() => {
    // Petit délai pour éviter le flash de contenu vide
    const timer = setTimeout(() => setIsLoading(false), 100);
    return () => clearTimeout(timer);
  }, []);

  // ✅ Mémoriser les fonctions de transformation pour éviter les recalculs
  const getPropertyData = useCallback((favorite: any) => {
    return favorite.property || favorite;
  }, []);

  const getImageUrl = useCallback((favorite: any): string => {
    const property = getPropertyData(favorite);
    
    if (property.photo) {
      let cleanUrl = property.photo;
      if (cleanUrl.includes('hstgr.io') || cleanUrl.includes('srv2197-files')) {
        const filename = cleanUrl.split('/').pop();
        if (filename && property.id) {
          cleanUrl = `https://api.bluefin-immo.com/api/property-image/${property.id}/${filename}`;
        }
      }
      return cleanUrl;
    }
    
    if (property.images && Array.isArray(property.images) && property.images.length > 0) {
      return property.images[0];
    }
    
    if (property.cover_photo) {
      if (typeof property.cover_photo === 'string') return property.cover_photo;
      if (property.cover_photo.photo_url) return property.cover_photo.photo_url;
      if (property.cover_photo.full_url) return property.cover_photo.full_url;
    }
    
    return '/placeholder-photo.svg';
  }, [getPropertyData]);

  const getPriceDisplay = useCallback((favorite: any): string => {
    const property = getPropertyData(favorite);
    const price = property.price_per_night || property.price || 0;
    const cleanPrice = typeof price === 'string' ? parseInt(price.replace(/\s/g, '')) : price;
    return `${cleanPrice.toLocaleString()} FCFA`;
  }, [getPropertyData]);

  const getRating = useCallback((favorite: any): number => {
    const property = getPropertyData(favorite);
    const rating = property.average_rating || property.rating || 0;
    return typeof rating === 'number' ? rating : parseFloat(rating) || 0;
  }, [getPropertyData]);

  const getReviews = useCallback((favorite: any): number => {
    const property = getPropertyData(favorite);
    return property.reviews_count || property.reviews || 0;
  }, [getPropertyData]);

  const getLocation = useCallback((favorite: any): string => {
    const property = getPropertyData(favorite);
    if (property.location) return property.location;
    const parts = [];
    if (property.district) parts.push(property.district);
    if (property.city) parts.push(property.city);
    return parts.length > 0 ? parts.join(', ') : 'Bénin';
  }, [getPropertyData]);

  const getTitle = useCallback((favorite: any): string => {
    const property = getPropertyData(favorite);
    return property.title || 'Logement sans titre';
  }, [getPropertyData]);

  const getPropertyId = useCallback((favorite: any): number => {
    const property = getPropertyData(favorite);
    return property.id;
  }, [getPropertyData]);

  // ✅ Optimisation: Mémoriser les favoris filtrés et triés
  const displayedFavorites = useMemo(() => {
    let filtered = [...favorites];
    switch (selectedFilter) {
      case 'Prix croissant':
        return filtered.sort((a, b) => {
          const priceA = parseInt((a.property?.price_per_night || '0').toString().replace(/\s/g, ''));
          const priceB = parseInt((b.property?.price_per_night || '0').toString().replace(/\s/g, ''));
          return priceA - priceB;
        });
      case 'Prix décroissant':
        return filtered.sort((a, b) => {
          const priceA = parseInt((a.property?.price_per_night || '0').toString().replace(/\s/g, ''));
          const priceB = parseInt((b.property?.price_per_night || '0').toString().replace(/\s/g, ''));
          return priceB - priceA;
        });
      case 'Mieux notés':
        return filtered.sort((a, b) => getRating(b) - getRating(a));
      default:
        return filtered;
    }
  }, [favorites, selectedFilter, getRating]);

  // ✅ Liste des filtres mémorisée
  const filtersList = useMemo(() => ['Tous', 'Prix croissant', 'Prix décroissant', 'Mieux notés'], []);

  // ✅ Composant de carte optimisé avec memo
  const FavoriteCard = useMemo(() => {
    return ({ favorite }: { favorite: any }) => {
      const propertyId = getPropertyId(favorite);
      const imageUrl = getImageUrl(favorite);
      const title = getTitle(favorite);
      const location = getLocation(favorite);
      const priceDisplay = getPriceDisplay(favorite);
      const rating = getRating(favorite);
      const reviews = getReviews(favorite);
      const propertyData = getPropertyData(favorite);
      
      return (
        <div 
          className="group rounded-2xl overflow-hidden border border-gray-200 shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer bg-white"
          onClick={() => onNavigate?.({ name: 'listing', id: propertyId.toString() })}
        >
          {/* Image - hauteur réduite sur mobile */}
          <div className="relative h-48 sm:h-52 md:h-56 overflow-hidden bg-gray-100">
            <img
              src={imageUrl}
              alt={title}
              className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110"
              loading="lazy"
              onError={(e) => {
                (e.target as HTMLImageElement).src = '/placeholder-photo.svg';
              }}
            />
            
            {/* Bouton retirer des favoris */}
            <button
              onClick={(e) => {
                e.stopPropagation();
                removeFavorite(propertyId);
              }}
              className="absolute top-3 right-3 p-2 rounded-full bg-white/90 hover:bg-white transition-colors z-10 shadow-md"
              aria-label="Retirer des favoris"
            >
              <Heart className="w-5 h-5 fill-red-500 text-red-500" />
            </button>
            
            {/* Badges */}
            <div className="absolute top-3 left-3 flex flex-col gap-1 z-10">
              {propertyData.bluefin_certified && (
                <div className="px-2 py-1 bg-blue-600 text-white text-xs rounded-full font-medium shadow-sm">
                  ✓ Bluefin Immo Certifié
                </div>
              )}
            </div>
            
            {propertyData.instant_booking && (
              <div className="absolute bottom-3 left-3 px-2 py-1 bg-green-600 text-white text-xs rounded-full z-10 shadow-sm">
                ⚡ Réservation instantanée
              </div>
            )}
          </div>
          
          {/* Contenu */}
          <div className="p-3 sm:p-4">
            <div className="flex justify-between items-start gap-2">
              <h3 className="font-semibold text-[#0F2940] text-sm sm:text-base line-clamp-1 flex-1">
                {title}
              </h3>
              {rating > 0 && (
                <div className="flex items-center gap-1 text-xs sm:text-sm flex-shrink-0">
                  <Star className="w-3 h-3 sm:w-4 sm:h-4 fill-yellow-500 text-yellow-500" />
                  <span className="font-medium">{rating.toFixed(1)}</span>
                  {reviews > 0 && (
                    <span className="text-gray-500 text-xs hidden sm:inline">({reviews})</span>
                  )}
                </div>
              )}
            </div>
            
            <p className="text-xs sm:text-sm text-gray-500 mt-1 line-clamp-1">{location}</p>
            
            {/* Équipements - cachés sur très petit mobile */}
            <div className="hidden sm:flex flex-wrap gap-2 mt-3">
              {propertyData.has_wifi && (
                <span className="inline-flex items-center gap-1 text-xs bg-gray-100 px-2 py-1 rounded-full">
                  📶 Wi-Fi
                </span>
              )}
              {propertyData.has_air_conditioning && (
                <span className="inline-flex items-center gap-1 text-xs bg-gray-100 px-2 py-1 rounded-full">
                  ❄️ Clim
                </span>
              )}
              {propertyData.has_generator && (
                <span className="inline-flex items-center gap-1 text-xs bg-gray-100 px-2 py-1 rounded-full">
                  ⚡ Groupe
                </span>
              )}
            </div>
            
            {/* Prix */}
            <div className="mt-3 pt-2 border-t border-gray-100">
              <div className="flex items-center justify-between">
                <div>
                  <span className="font-bold text-base sm:text-lg text-[#00c9a7]">{priceDisplay}</span>
                  <span className="text-xs sm:text-sm text-gray-400"> / nuit</span>
                </div>
                <button 
                  className="text-xs sm:text-sm text-[#00c9a7] hover:text-[#0F2940] font-medium transition-colors"
                  onClick={(e) => {
                    e.stopPropagation();
                    onNavigate?.({ name: 'listing', id: propertyId.toString() });
                  }}
                >
                  Voir →
                </button>
              </div>
            </div>
          </div>
        </div>
      );
    };
  }, [onNavigate, removeFavorite, getPropertyId, getImageUrl, getTitle, getLocation, getPriceDisplay, getRating, getReviews, getPropertyData]);

  // ✅ État de chargement
  if (isLoading) {
    return (
      <div className="min-h-screen bg-white py-10">
        <div className="max-w-[1100px] mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-9 h-9 bg-gray-200 rounded-full animate-pulse"></div>
            <div className="h-8 w-32 bg-gray-200 rounded animate-pulse"></div>
            <div className="h-5 w-20 bg-gray-200 rounded animate-pulse"></div>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="bg-gray-200 rounded-2xl h-48 mb-3"></div>
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                <div className="h-3 bg-gray-200 rounded w-1/2"></div>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // ✅ État vide
  if (!favorites || favorites.length === 0) {
    return (
      <div className="min-h-screen bg-white py-10">
        <div className="max-w-[1100px] mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center gap-4 mb-6">
            <button
              onClick={() => onNavigate?.({ name: 'home' })}
              className="p-2 rounded-full hover:bg-gray-100 transition-colors"
            >
              <ArrowLeft className="w-5 h-5 text-[#0F2940]" />
            </button>
            <h1 className="text-2xl font-bold text-[#0F2940]">Mes favoris</h1>
            <span className="text-sm text-gray-500">(0 logement)</span>
          </div>
          <div className="text-center py-16">
            <Heart className="w-16 h-16 text-gray-300 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-[#0F2940] mb-2">Aucun favori</h2>
            <p className="text-gray-500 mb-6">Les logements que vous ajoutez aux favoris apparaissent ici.</p>
            <button
              onClick={() => onNavigate?.({ name: 'home' })}
              className="px-6 py-3 bg-[#00c9a7] text-white rounded-full font-semibold hover:bg-[#00b892] transition-colors"
            >
              Découvrir des logements
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ✅ Vue principale
  return (
    <div className="min-h-screen bg-white py-4 sm:py-10">
      <div className="max-w-[1100px] mx-auto px-3 sm:px-6 lg:px-8">
        {/* En-tête - sticky sur mobile */}
        <div className="sticky top-0 bg-white/95 backdrop-blur-sm z-10 py-3 -mt-2 mb-4 sm:static sm:bg-transparent sm:py-0 sm:mb-6">
          <div className="flex items-center gap-3 sm:gap-4">
            <button
              onClick={() => onNavigate?.({ name: 'home' })}
              className="p-2 rounded-full hover:bg-gray-100 transition-colors active:bg-gray-200"
            >
              <ArrowLeft className="w-5 h-5 text-[#0F2940]" />
            </button>
            <h1 className="text-xl sm:text-2xl font-bold text-[#0F2940]">Mes favoris</h1>
            <span className="text-xs sm:text-sm text-gray-500 bg-gray-100 px-2 py-1 rounded-full">
              {displayedFavorites.length}
            </span>
          </div>
        </div>

        {/* Filtres - scroll horizontal sur mobile */}
        <div className="mb-4 sm:mb-6 overflow-x-auto -mx-3 px-3 sm:mx-0 sm:px-0">
          <div className="flex gap-2 pb-2 min-w-max sm:min-w-0">
            {filtersList.map(filter => (
              <button
                key={filter}
                onClick={() => setSelectedFilter(filter)}
                className={`px-3 sm:px-4 py-1.5 sm:py-2 rounded-full text-xs sm:text-sm transition-all duration-200 whitespace-nowrap ${
                  selectedFilter === filter 
                    ? 'bg-[#00c9a7] text-white shadow-md scale-105' 
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                {filter}
              </button>
            ))}
          </div>
        </div>

        {/* Grille des favoris - 2 colonnes sur mobile, 3 sur desktop */}
        <div className="grid grid-cols-2 gap-3 sm:gap-6 lg:grid-cols-3">
          {displayedFavorites.map((favorite, index) => (
            <FavoriteCard key={favorite.id || index} favorite={favorite} />
          ))}
        </div>

        {/* Message de fin */}
        {displayedFavorites.length >= 4 && (
          <div className="text-center mt-8 sm:mt-12 text-gray-400 text-xs sm:text-sm">
            — Fin de la liste —
          </div>
        )}
      </div>
    </div>
  );
}
// ==================== PUBLISH LISTING PAGE ====================

