// ========== PAGE COMPANY INFO ==========


interface PageProps {
  onNavigate?: (page: { name: string }) => void;
}

export function CompanyInfoPage({ onNavigate }: PageProps) {
  // Mentions légales — identification de l'exploitant, conformément à l'article 328
  // (obligation générale d'information, commerce électronique) et à l'article 501
  // (identification de l'éditeur d'un service de communication au public en ligne)
  // de la loi n° 2017-20 portant Code du numérique en République du Bénin.
  //
  // Les champs marqués "À compléter" ne peuvent pas être renseignés automatiquement :
  // ce sont des données d'immatriculation réelles (RCCM, IFU) que seule l'entreprise
  // détient. Ils ne doivent jamais être remplis avec des valeurs inventées.
  const identite = [
    { label: "Exploitant", value: LEGAL_INFO.entityName },
    { label: "Forme juridique", value: LEGAL_INFO.formeJuridique },
    { label: "Siège social", value: LEGAL_INFO.siegeSocial },
    { label: "Registre du Commerce et du Crédit Mobilier (RCCM)", value: LEGAL_INFO.rccm },
    { label: "Capital social", value: LEGAL_INFO.capitalSocial },
    { label: "Numéro d'Identifiant Fiscal Unique (IFU)", value: LEGAL_INFO.ifu },
    { label: "Directeur de la publication", value: LEGAL_INFO.directeurPublication },
    { label: "Téléphone", value: LEGAL_INFO.telephone },
    { label: "Email", value: LEGAL_INFO.email },
    { label: "Hébergeur", value: LEGAL_INFO.hebergeur },
  ];

  const sections = [
    { title: "1. Activité", content: "Bluefin Immo édite une plateforme de mise en relation entre hôtes et voyageurs pour la location de logements meublés de courte durée au Bénin, ainsi que pour la réservation d'expériences et de services associés. Le paiement s'effectue en ligne, notamment par Mobile Money (MTN, Moov, Orange)." },
    { title: "2. Propriété intellectuelle", content: "L'ensemble des contenus présents sur la plateforme Bluefin Immo — nom, logo, textes, visuels et architecture du site — sont la propriété exclusive de Bluefin Immo ou de ses concédants, et sont protégés par les lois applicables en matière de propriété intellectuelle." },
    { title: "3. Protection des données personnelles", content: "Bluefin Immo, responsable du traitement, collecte et traite les données personnelles de ses utilisateurs dans le cadre strict de la fourniture de ses services (gestion des comptes, traitement des réservations et des paiements, amélioration de la plateforme), conformément à la loi n° 2017-20 portant Code du numérique et sous le contrôle de l'Autorité de Protection des Données Personnelles (APDP) du Bénin. Les modalités complètes (finalités, durée de conservation, droits d'accès, de rectification, d'opposition et de réclamation auprès de l'APDP) sont détaillées dans notre politique de confidentialité." },
    { title: "4. Droit applicable et juridiction", content: "Les présentes mentions légales sont régies par le droit béninois, notamment la loi n° 2017-20 portant Code du numérique en République du Bénin. Tout litige relève de la compétence exclusive des juridictions béninoises." },
  ];

  return (
    <Layout onNavigate={onNavigate} currentPage="company-info">
      <div className="max-w-4xl mx-auto px-5 py-8 md:px-6 md:py-10">
        <div className="sticky top-0 z-40 bg-white border-b border-gray-100 px-5 py-4 -mt-8 -mx-5 md:-mx-6 mb-8">
          <h1 className="text-2xl text-[#0F2940]">Informations légales</h1>
          <p className="text-sm text-gray-500 mt-1">Mentions légales — article 328 et 501 de la loi n° 2017-20 (Code du numérique, Bénin)</p>
        </div>

        {identite.some((item) => item.value === LEGAL_PLACEHOLDER) && (
          <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 mb-8">
            <p className="text-sm text-amber-800">
              Certaines informations d'immatriculation sont en cours de finalisation et seront publiées dès leur
              délivrance. Nous ne publions jamais de numéro d'immatriculation fictif.
            </p>
          </div>
        )}

        <div className="mb-10">
          <h2 className="text-xl font-semibold text-[#0F2940] mb-4">Identification de l'exploitant</h2>
          <dl className="grid sm:grid-cols-2 gap-4">
            {identite.map((item, idx) => (
              <div key={idx} className="bg-[#f4fffe] rounded-xl p-4">
                <dt className="text-sm text-gray-500 mb-1">{item.label}</dt>
                <dd className={`font-semibold ${item.value === LEGAL_PLACEHOLDER ? 'text-amber-600' : 'text-[#0F2940]'}`}>{item.value}</dd>
              </div>
            ))}
          </dl>
        </div>

        <div className="space-y-8">
          {sections.map((section, idx) => (
            <div key={idx} className="border-b border-gray-200 pb-6">
              <h2 className="text-xl font-semibold text-[#0F2940] mb-3">{section.title}</h2>
              <p className="text-gray-600 leading-relaxed whitespace-pre-line">{section.content}</p>
            </div>
          ))}
        </div>

      </div>
    </Layout>
  );
}


